module Comunicador(
input wire Reset,
input wire Clk,
input wire RS232_RX,
output wire RS232_TX,
input wire SEND,
input wire DMA_ACK,
output wire READY,
output wire DMA_RQ,
output wire [7:0] Switches,
output wire [6:0] Temp_L,
output wire [6:0] Temp_H
);
//---------------------------------------------------------------------------------
// Módulos de comunicación
//---------------------------------------------------------------------------------
//-----------------------------------------------------------------------------
// Memoria RAM
//-----------------------------------------------------------------------------
//-------------------------------------------------------------------
// Señales internas
//-------------------------------------------------------------------
wire Valid_D;
wire Ack_out;
wire TX_RDY;
wire Data_Read;
wire RX_Full;
wire RX_Empty;
wire Write_en;
wire OE;
wire [7:0] TX_Data;
wire [7:0] Address;
wire [7:0] Databus;
wire [7:0] RCVD_Data;
wire [5:0] fifo_count;
  // behavior
  RS232top RS232_PHY(
      .Reset(Reset),
    .Clk(Clk),
    .Data_in(TX_Data),
    .Valid_D(Valid_D),
    .Ack_in(Ack_out),
    .TX_RDY(TX_RDY),
    .TD(RS232_TX),
    .RD(RS232_RX),
    .Data_out(RCVD_Data),
    .Data_read(Data_Read),
    .Full(RX_Full),
    .Empty(RX_Empty),
    .FF_Count(fifo_count));
  DMA DMA_Unit(
      .Reset(Reset),
    .Clk(Clk),
    .RCVD_Data(RCVD_Data),
    .RX_Full(RX_Full),
    .RX_Empty(RX_Empty),
    .Data_Read(Data_Read),
    .ACK_out(ACK_out),
    .TX_RDY(TX_RDY),
    .Valid_D(Valid_D),
    .TX_Data(TX_Data),
    .Address(Address),
    .Databus(Databus),
    .Write_en(Write_en),
    .OE(OE),
    .DMA_RQ(DMA_RQ),
    .DMA_ACK(DMA_ACK),
    .Send_comm(SEND),
    .READY(READY),
    .FF_Count(fifo_count));
  RAM RAM_Unit(
      .Clk(Clk),
    .Reset(Reset),
    .write_en(Write_en),
    .oe(OE),
    .address(Address),
    .databus(Databus),
    .Switches(Switches),
    .Temp_L(Temp_L),
    .Temp_H(Temp_H));
endmodule

module lcd_driver (
  input clk,
  input rst,
  input [7:0] data,
  input rs,
  input en,
  output reg [7:0] lcd_data,
  output reg lcd_rs,
  output reg lcd_en
);

  // Internal registers
  reg [7:0] cgram_addr;
  reg [7:0] ddram_addr;
  reg [7:0] busy_flag;
  reg [7:0] instruction;
  reg [7:0] display_data;

  // Internal states
  parameter IDLE = 2'b00;
  parameter READ_BUSY_FLAG = 2'b01;
  parameter READ_ADDRESS = 2'b10;
  parameter WRITE_DATA = 2'b11;
  reg [1:0] state;

  always @(posedge clk) begin
    if (rst) begin
      // Reset all internal registers and states
      cgram_addr <= 8'b0;
      ddram_addr <= 8'b0;
      busy_flag <= 8'b0;
      instruction <= 8'b0;
      display_data <= 8'b0;
      state <= IDLE;

      // Reset all output signals
      lcd_data <= 8'b0;
      lcd_rs <= 1'b0;
      lcd_en <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (en) begin
            if (rs) begin
              // Write data to DDRAM or CGRAM
              state <= WRITE_DATA;
              lcd_data <= display_data;
              lcd_rs <= 1'b1;
              lcd_en <= 1'b1;
            end else begin
              // Execute instruction
              instruction <= data;
              if (instruction[7:4] == 4'b0000) begin
                // Clear display
                state <= READ_BUSY_FLAG;
                lcd_data <= 8'b00000001;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end else if (instruction[7:4] == 4'b0001) begin
                // Return home
                state <= READ_BUSY_FLAG;
                lcd_data <= 8'b00000010;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end else if (instruction[7:4] == 4'b0010) begin
                // Entry mode set
                state <= READ_BUSY_FLAG;
                lcd_data <= instruction;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end else if (instruction[7:4] == 4'b0011) begin
                // Display on/off control
                state <= READ_BUSY_FLAG;
                lcd_data <= instruction;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end else if (instruction[7:4] == 4'b0100 || instruction[7:4] == 4'b0101) begin
                // Cursor or display shift
                state <= READ_BUSY_FLAG;
                lcd_data <= instruction;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end else if (instruction[7:4] == 4'b0010) begin
                // Function set
                state <= READ_BUSY_FLAG;
                lcd_data <= instruction;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end else if (instruction[7:4] == 4'b0110 || instruction[7:4] == 4'b0111) begin
                // Set CGRAM address or DDRAM address
                state <= READ_ADDRESS;
                lcd_data <= instruction;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end else if (instruction[7:4] == 4'b1000 || instruction[7:4] == 4'b1001) begin
                // Read busy flag and address
                state <= READ_BUSY_FLAG;
                lcd_rs <= 1'b0;
                lcd_en <= 1'b1;
              end
            end
          end
        end

        READ_BUSY_FLAG: begin
          // Read busy flag and address
          lcd_data <= 8'b0;
          lcd_rs <= 1'b0;
          lcd_en <= 1'b1;
          state <= READ_ADDRESS;
        end

        READ_ADDRESS: begin
          // Read address
          busy_flag <= lcd_data;
          lcd_rs <= 1'b0;
          lcd_en <= 1'b0;
          if (instruction[7:4] == 4'b0110) begin
            // Set CGRAM address
            cgram_addr <= lcd_data;
          end else begin
            // Set DDRAM address
            ddram_addr <= lcd_data;
          end
          state <= IDLE;
        end

        WRITE_DATA: begin
          // Write data to DDRAM or CGRAM
          lcd_rs <= 1'b1;
          lcd_en <= 1'b0;
          if (instruction[7:4] == 4'b0100) begin
            // Write data to CGRAM
            state <= READ_ADDRESS;
            lcd_data <= cgram_addr;
          end else begin
            // Write data to DDRAM
            state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

module cbcaes(
input wire reset_i,
input wire clk_i,
input wire start_i,
input wire mode_i,
input wire [0:127] key_i,
input wire [0:127] iv_i,
input wire [0:127] data_i,
input wire valid_i,
output wire accept_o,
output wire [0:127] data_o,
output wire valid_o,
input wire accept_i
);
// low active async reset
// clock
// start cbc
// aes-modus: 0 = encrypt, 1 = decrypt
// key input
// iv input
// data input
// input key/data valid flag
// ready to encrypt/decrypt
// data output
// output data valid flag
reg s_mode;
wire s_aes_mode;
reg s_start;
reg [0:127] s_key;
wire [0:127] s_aes_key;
reg [0:127] s_iv;
reg [0:127] s_datain;
reg [0:127] s_datain_d;
wire [0:127] s_aes_datain;
wire [0:127] s_aes_dataout;
reg [0:127] s_dataout;
  assign s_aes_datain = mode_i == 1'b0 && start_i == 1'b1 ? iv_i ^ data_i : s_mode == 1'b0 && start_i == 1'b0 ? s_dataout ^ data_i : data_i;
  assign data_o = s_mode == 1'b1 && s_start == 1'b1 ? s_iv ^ s_aes_dataout : s_mode == 1'b1 && s_start == 1'b0 ? s_datain_d ^ s_aes_dataout : s_aes_dataout;
  assign s_aes_key = start_i == 1'b1 ? key_i : s_key;
  assign s_aes_mode = start_i == 1'b1 ? mode_i : s_mode;
  always @(posedge clk_i, posedge reset_i) begin
    if((reset_i == 1'b0)) begin
      s_mode <= 1'b0;
      s_start <= 1'b0;
      s_key <= {128{1'b0}};
      s_iv <= {128{1'b0}};
      s_datain <= {128{1'b0}};
      s_datain_d <= {128{1'b0}};
    end else begin
      if((valid_i == 1'b1 && accept_o == 1'b1)) begin
        s_start <= start_i;
        s_datain <= data_i;
        s_datain_d <= s_datain;
        if((start_i == 1'b1)) begin
          s_mode <= mode_i;
          s_key <= key_i;
          s_iv <= iv_i;
        end
      end
    end
  end
  always @(posedge clk_i, posedge reset_i) begin
    if((reset_i == 1'b0)) begin
      s_dataout <= {128{1'b0}};
    end else begin
      if((valid_o == 1'b1 && accept_i == 1'b1)) begin
        s_dataout <= s_aes_dataout;
      end
    end
  end
  aes #(
      .design_type(4'bITER))
  i_aes(
      .reset_i(reset_i),
    .clk_i(clk_i),
    .mode_i(s_aes_mode),
    .key_i(s_aes_key),
    .data_i(s_aes_datain),
    .valid_i(valid_i),
    .accept_o(accept_o),
    .data_o(s_aes_dataout),
    .valid_o(valid_o),
    .accept_i(accept_i));
endmodule

module circuita(
input wire [2:0] INPUT,
output wire [2:0] OUTPUT
);
// (2)=A, (1)=B, (0)=C
// F0, F1, F2
  assign OUTPUT[0] = INPUT[0];
  assign OUTPUT[1] =  ~INPUT[1];
  assign OUTPUT[2] = INPUT[2] | INPUT[1];
endmodule

module booth_multiplier (
  input clk,
  input resetn,
  input signed [3:0] multiplier,
  input signed [3:0] multiplicand,
  output signed [7:0] product
);

reg signed [7:0] partial_product;
reg signed [3:0] multiplicand_shifted;
reg signed [3:0] multiplier_shifted;
reg signed [3:0] correction_factor;

always @(posedge clk or negedge resetn) begin
  if (!resetn) begin
    partial_product <= 0;
    multiplicand_shifted <= 0;
    multiplier_shifted <= 0;
    correction_factor <= 0;
  end else begin
    // Shift the multiplicand and multiplier
    multiplicand_shifted <= {multiplicand[3], multiplicand[3:1]};
    multiplier_shifted <= {multiplier[0], multiplier[3:1]};

    // Determine the correction factor based on the last two bits of the multiplier
    case (multiplier[1:0])
      2'b00: correction_factor <= 4'b0000;
      2'b01: correction_factor <= 4'b1111;
      2'b10: correction_factor <= {2'b10, multiplicand};
      2'b11: correction_factor <= {2'b10, ~multiplicand + 1};
    endcase

    // Add or subtract the correction factor from the partial product
    if (multiplier[0] == 1) begin
      partial_product <= partial_product - correction_factor;
    end else begin
      partial_product <= partial_product + correction_factor;
    end
  end
end

assign product = partial_product;

endmodule

module serialLoader(
output reg S_Send,
output reg [7:0] S_DataOut,
input wire S_Ready,
input wire FIFO_Empty,
input wire [7:0] FIFO_Data,
output reg FIFO_ReadEn,
input wire clk,
input wire reset
);
//serial control data
//FIFO DATA
// flag if no data is left
// actual data
// enable read
// global clock
parameter [2:0]
  STATE_WAIT = 0,
  STATE_STARTREAD = 1,
  STATE_ENDREAD = 2,
  STATE_STARTWRITE = 3,
  STATE_ENDWRITE = 4,
  STATE_CLOCKIN = 5;
reg [2:0] state_reg = STATE_WAIT;
  always @(posedge clk, posedge FIFO_Empty, posedge S_Ready, posedge reset) begin : P1
  // process to handle the next state
    if((reset == 1'b1)) begin
      //reset state:
      FIFO_ReadEn <= 1'b0;
      S_Send <= 1'b0;
      state_reg <= STATE_WAIT;
    end else begin
      case(state_reg)
      STATE_WAIT : begin
        if((FIFO_Empty == 1'b1 || S_Ready == 1'b0)) begin
          state_reg <= STATE_WAIT;
        end
        else begin
          state_reg <= STATE_STARTREAD;
        end
      end
      STATE_STARTREAD : begin
        // request the data
        FIFO_ReadEn <= 1'b1;
        state_reg <= STATE_ENDREAD;
      end
      STATE_ENDREAD : begin
        FIFO_ReadEn <= 1'b0;
        state_reg <= STATE_CLOCKIN;
      end
      STATE_CLOCKIN : begin
        //clock the data out
        S_DataOut <= FIFO_Data;
        state_reg <= STATE_STARTWRITE;
      end
      STATE_STARTWRITE : begin
        // tell the serial module to pickup the data
        S_Send <= 1'b1;
        state_reg <= STATE_ENDWRITE;
      end
      STATE_ENDWRITE : begin
        // close all the modules down
        S_Send <= 1'b0;
        //if (FIFO_Empty = '0' and S_Ready = '1') then
        //    state_reg <= STATE_STARTREAD;
        //else
        state_reg <= STATE_WAIT;
        //end if;
      end
      default : begin
        state_reg <= STATE_WAIT;
      end
      endcase
    end
  end
endmodule

module control(
input wire [5:0] Opcode,
input wire [5:0] Function_opcode,
output wire RegDst,
output wire RegWrite,
output wire ALUSrc,
output wire MemToReg,
output wire MemRead,
output wire MemWrite,
inout wire Beq,
inout wire Bne,
output wire Jump,
output wire Jal,
output wire Jr,
output wire Sl,
output wire Sr,
output wire [1:0] ALUOp
);
// *** Acrescentar a linha abaixo a sua unidade para selecionar as operações
// Será mapeado para o execute
wire R_format;
wire SW;
wire LW;
wire ADDi;
  // Code to generate control signals using opcode bits
  assign R_format = Opcode == 6'b000000 ? 1'b1 : 1'b0;
  assign SW = Opcode == 6'b101011 ? 1'b1 : 1'b0;
  assign LW = Opcode == 6'b100011 ? 1'b1 : 1'b0;
  assign Beq = Opcode == 6'b000100 ? 1'b1 : 1'b0;
  assign Bne = Opcode == 6'b000101 ? 1'b1 : 1'b0;
  assign Jump = Opcode == 6'b000010 ? 1'b1 : 1'b0;
  assign Jal = Opcode == 6'b000011 ? 1'b1 : 1'b0;
  assign ADDi = Opcode == 6'b001000 ? 1'b1 : 1'b0;
  assign Jr = R_format == 1'b1 && Function_opcode == 6'b001000 ? 1'b1 : 1'b0;
  assign Sl = R_format == 1'b1 && Function_opcode == 6'b000000 ? 1'b1 : 1'b0;
  assign Sr = R_format == 1'b1 && Function_opcode == 6'b000010 ? 1'b1 : 1'b0;
  assign RegDst = R_format;
  assign RegWrite = R_format | LW | ADDi;
  assign ALUSrc = LW | SW | ADDi;
  assign MemToReg = LW;
  assign MemRead = LW;
  assign MemWrite = SW;
  // *** ACRESCENTE AS ATRIBUIÇÕES ABAIXO
  assign ALUOp[1] = R_format;
  assign ALUOp[0] = Beq | Bne;
    // Beq deve ser 1 quando a instrução for BEQ (BNE também)
endmodule

module result_fsm(
input wire clk,
input wire rst,
input wire start,
output reg finish,
input wire sysrst,
output wire rstdone,
input wire rnw,
input wire [0:C_DWIDTH - 1] datain,
output reg [0:C_DWIDTH - 1] data
);
parameter [31:0] C_AWIDTH=32;
parameter [31:0] C_DWIDTH=32;
parameter [31:0] C_TWIDTH=8;
parameter [31:0] C_MWIDTH=6;
parameter [31:0] C_CWIDTH=8;
// Declare signals for the results register
reg [0:C_DWIDTH - 1] results = 1'b0;
  // This core resets in one clock cycle so it is always "done"
  assign rstdone = 1'b1;
  always @(posedge clk, posedge rst, posedge sysrst, posedge start, posedge results, posedge datain, posedge rnw) begin
    data <= {((C_DWIDTH - 1)-(0)+1){1'b0}};
    finish <= 1'b0;
    if((rst == 1'b1 || sysrst == 1'b1)) begin
      results <= {((C_DWIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      results <= results;
      if((start == 1'b1)) begin
        if((rnw == 1'b1)) begin
          results <= datain;
        end
        else begin
          data <= results;
        end
        finish <= 1'b1;
      end
    end
  end
endmodule

