module hex_7seg(
input wire [4:0] hex_digit,
output wire segment_a,
output wire segment_b,
output wire segment_c,
output wire segment_d,
output wire segment_e,
output wire segment_f,
output wire segment_g
);
reg [6:0] segment_data;
  always @(Hex_digit) begin : P1
  // HEX to 7 Segment Decoder for LED Display
    // Hex-digit is the four bit binary value to display in hexadecimal
    case(Hex_digit)
    5'b00000 : begin
      segment_data <= 7'b0000001;
      //0
    end
    5'b00001 : begin
      segment_data <= 7'b1001111;
      //1
    end
    5'b00010 : begin
      segment_data <= 7'b0010010;
      //2
    end
    5'b00011 : begin
      segment_data <= 7'b0000110;
      //3
    end
    5'b00100 : begin
      segment_data <= 7'b1001100;
      //4
    end
    5'b00101 : begin
      segment_data <= 7'b0100100;
      //5
    end
    5'b00110 : begin
      segment_data <= 7'b0100000;
      //6
    end
    5'b00111 : begin
      segment_data <= 7'b0001111;
      //7
    end
    5'b01000 : begin
      segment_data <= 7'b0000000;
      //8
    end
    5'b01001 : begin
      segment_data <= 7'b0000100;
      //9
    end
    5'b01010 : begin
      segment_data <= 7'b0001000;
      //10 - A 
    end
    5'b01011 : begin
      segment_data <= 7'b1100000;
      //11 - B
    end
    5'b01100 : begin
      segment_data <= 7'b0110001;
      //12 - C
    end
    5'b01101 : begin
      segment_data <= 7'b1000010;
      //13 - D
    end
    5'b01110 : begin
      segment_data <= 7'b0110000;
      //14 - E
    end
    5'b01111 : begin
      segment_data <= 7'b0111000;
      //15 - F
    end
    5'b10000 : begin
      segment_data <= 7'b1110001;
      //L
    end
    5'b10001 : begin
      segment_data <= 7'b1111110;
      //'-'
    end
    default : begin
      segment_data <= 7'b1111111;
    end
    endcase
  end
  // extract segment data bits
  // LED driver circuit
  assign segment_a = segment_data[6];
  assign segment_b = segment_data[5];
  assign segment_c = segment_data[4];
  assign segment_d = segment_data[3];
  assign segment_e = segment_data[2];
  assign segment_f = segment_data[1];
  assign segment_g = segment_data[0];
endmodule

