      Read_To_Reg_r <= 5'b00000;
      F <= {8{1'b1}};
      Arith16_r <= 1'b0;
      BTR_r <= 1'b0;
      Z16_r <= 1'b0;
      ALU_Op_r <= 4'b0000;
      ALU_cpi_r <= 1'b0;
      Save_ALU_r <= 1'b0;
      PreserveC_r <= 1'b0;
      XY_Ind <= 1'b0;
    end else begin
      if(ClkEn == 1'b1) begin
        ALU_Op_r <= 4'b0000;
        ALU_cpi_r <= 1'b0;
        Save_ALU_r <= 1'b0;
        Read_To_Reg_r <= 5'b00000;
        MCycles <= MCycles_d;
        if(IMode != 2'b11) begin
          IStatus <= IMode;
        end
        Arith16_r <= Arith16;
        PreserveC_r <= PreserveC;
        if(ISet == 2'b10 && ALU_OP[2] == 1'b0 && ALU_OP[0] == 1'b1 && MCycle == 3'b011) begin
          Z16_r <= 1'b1;
        end
        else begin
          Z16_r <= 1'b0;
        end
        if(MCycle == 3'b001 && TState[2] == 1'b0) begin
          // MCycle = 1 and TState = 1, 2, or 3
          if(TState == 2 && Wait_n == 1'b1) begin
            if(Mode < 2) begin
              A[7:0] <= R;
              A[15:8] <= I;
              R[6:0] <= R[6:0] + 1;
            end
            if(Jump == 1'b0 && Call == 1'b0 && NMICycle == 1'b0 && IntCycle == 1'b0 && !(Halt_FF == 1'b1 || Halt == 1'b1)) begin
              PC <= PC + 1;
            end
            if(IntCycle == 1'b1 && IStatus == 2'b01) begin
              IR <= 8'b11111111;
            end
            else if(Halt_FF == 1'b1 || (IntCycle == 1'b1 && IStatus == 2'b10) || NMICycle == 1'b1) begin
              IR <= 8'b00000000;
            end
            else begin
              IR <= DInst;
            end
            ISet <= 2'b00;
            if(Prefix != 2'b00) begin
              if(Prefix == 2'b11) begin
                if(IR[5] == 1'b1) begin
                  XY_State <= 2'b10;
                end
                else begin
                  XY_State <= 2'b01;
                end
              end
              else begin
                if(Prefix == 2'b10) begin
                  XY_State <= 2'b00;
                  XY_Ind <= 1'b0;
                end
                ISet <= Prefix;
              end
            end
            else begin
              XY_State <= 2'b00;
              XY_Ind <= 1'b0;
            end
          end
        end
        else begin
          // either (MCycle > 1) OR (MCycle = 1 AND TState > 3)
          if(MCycle == 3'b110) begin
            XY_Ind <= 1'b1;
            if(Prefix == 2'b01) begin
              ISet <= 2'b01;
            end
          end
          if(T_Res == 1'b1) begin
            BTR_r <= (I_BT | I_BC | I_BTR) &  ~No_BTR;
            if(Jump == 1'b1) begin
              A[15:8] <= DI_Reg;
              A[7:0] <= TmpAddr[7:0];
              PC[15:8] <= DI_Reg;
              PC[7:0] <= TmpAddr[7:0];
            end
            else if(JumpXY == 1'b1) begin
              A <= RegBusC;
              PC <= RegBusC;
            end
            else if(Call == 1'b1 || RstP == 1'b1) begin
              A <= TmpAddr;
              PC <= TmpAddr;
            end
            else if(MCycle == MCycles && NMICycle == 1'b1) begin
              A <= 16'b0000000001100110;
              PC <= 16'b0000000001100110;
            end
            else if(MCycle == 3'b011 && IntCycle == 1'b1 && IStatus == 2'b10) begin
              A[15:8] <= I;
              A[7:0] <= TmpAddr[7:0];
              PC[15:8] <= I;
              PC[7:0] <= TmpAddr[7:0];
            end
            else begin
              case(Set_Addr_To)
              aXY : begin
                if(XY_State == 2'b00) begin
                  A <= RegBusC;
                end
                else begin
                  if(NextIs_XY_Fetch == 1'b1) begin
                    A <= PC;
                  end
                  else begin
                    A <= TmpAddr;
                  end
                end
              end
              aIOA : begin
                if(Mode == 3) begin
                  // Memory map I/O on GBZ80
                  A[15:8] <= {8{1'b1}};
                end
                else if(Mode == 2) begin
                  // Duplicate I/O address on 8080
                  A[15:8] <= DI_Reg;
                end
                else begin
                  A[15:8] <= ACC;
                end
                A[7:0] <= DI_Reg;
              end
              aSP : begin
                A <= SP;
              end
              aBC : begin
                if(Mode == 3 && IORQ_i == 1'b1) begin
                  // Memory map I/O on GBZ80
                  A[15:8] <= {8{1'b1}};
                  A[7:0] <= RegBusC[7:0];
                end
                else begin
                  A <= RegBusC;
                end
              end
              aDE : begin
                A <= RegBusC;
              end
              aZI : begin
                if(Inc_WZ == 1'b1) begin
                  A <= (TmpAddr) + 1;
                end
                else begin
                  A[15:8] <= DI_Reg;
                  A[7:0] <= TmpAddr[7:0];
                end
              end
              default : begin
                A <= PC;
              end
              endcase
            end
            Save_ALU_r <= Save_ALU;
            ALU_cpi_r <= ALU_cpi;
            ALU_Op_r <= ALU_Op;
            if(I_CPL == 1'b1) begin
              // CPL
              ACC <=  ~ACC;
              F[Flag_Y] <=  ~ACC[5];
              F[Flag_H] <= 1'b1;
              F[Flag_X] <=  ~ACC[3];
              F[Flag_N] <= 1'b1;
            end
            if(I_CCF == 1'b1) begin
              // CCF
              F[Flag_C] <=  ~F[Flag_C];
              F[Flag_Y] <= ACC[5];
              F[Flag_H] <= F[Flag_C];
              F[Flag_X] <= ACC[3];
              F[Flag_N] <= 1'b0;
            end
            if(I_SCF == 1'b1) begin
              // SCF
              F[Flag_C] <= 1'b1;
              F[Flag_Y] <= ACC[5];
              F[Flag_H] <= 1'b0;
              F[Flag_X] <= ACC[3];
              F[Flag_N] <= 1'b0;
            end
          end
          if(TState == 2 && Wait_n == 1'b1) begin
            if(ISet == 2'b01 && MCycle == 3'b111) begin
              IR <= DInst;
            end
            if(JumpE == 1'b1) begin
              PC <= (PC) + (DI_Reg);
            end
            else if(Inc_PC == 1'b1) begin
              PC <= PC + 1;
            end
            if(BTR_r == 1'b1) begin
              PC <= PC - 2;
            end
            if(RstP == 1'b1) begin
              TmpAddr <= {16{1'b0}};
              TmpAddr[5:3] <= IR[5:3];
            end
          end
          if(TState == 3 && MCycle == 3'b110) begin
            TmpAddr <= (RegBusC) + (DI_Reg);
          end
          if((TState == 2 && Wait_n == 1'b1) || (TState == 4 && MCycle == 3'b001)) begin
            if(IncDec_16[2:0] == 3'b111) begin
              if(IncDec_16[3] == 1'b1) begin
                SP <= SP - 1;
              end
              else begin
                SP <= SP + 1;
              end
            end
          end
          if(LDSPHL == 1'b1) begin
            SP <= RegBusC;
          end
          if(ExchangeAF == 1'b1) begin
            Ap <= ACC;
            ACC <= Ap;
            Fp <= F;
            F <= Fp;
          end
          if(ExchangeRS == 1'b1) begin
            Alternate <=  ~Alternate;
          end
        end
        if(TState == 3) begin
          if(LDZ == 1'b1) begin
            TmpAddr[7:0] <= DI_Reg;
          end
          if(LDW == 1'b1) begin
            TmpAddr[15:8] <= DI_Reg;
          end
          if(Special_LD[2] == 1'b1) begin
            case(Special_LD[1:0])
            2'b00 : begin
              ACC <= I;
              F[Flag_P] <= IntE_FF2;
            end
            2'b01 : begin
              ACC <= R;
              F[Flag_P] <= IntE_FF2;
            end
            2'b10 : begin
              I <= ACC;
            end
            default : begin
              R <= ACC;
            end
            endcase
          end
        end
        if((I_DJNZ == 1'b0 && Save_ALU_r == 1'b1) || ALU_Op_r == 4'b1001) begin
          if(Mode == 3) begin
            F[6] <= F_Out[6];
            F[5] <= F_Out[5];
            F[7] <= F_Out[7];
            if(PreserveC_r == 1'b0) begin
              F[4] <= F_Out[4];
            end
          end
          else begin
            F[7:1] <= F_Out[7:1];
            if(PreserveC_r == 1'b0) begin
              F[Flag_C] <= F_Out[0];
            end
          end
        end
        if(T_Res == 1'b1 && I_INRC == 1'b1) begin
          F[Flag_H] <= 1'b0;
          F[Flag_N] <= 1'b0;
          if(DI_Reg[7:0] == 8'b00000000) begin
            F[Flag_Z] <= 1'b1;
          end
          else begin
            F[Flag_Z] <= 1'b0;
          end
          F[Flag_S] <= DI_Reg[7];
          F[Flag_P] <=  ~(DI_Reg[0] ^ DI_Reg[1] ^ DI_Reg[2] ^ DI_Reg[3] ^ DI_Reg[4] ^ DI_Reg[5] ^ DI_Reg[6] ^ DI_Reg[7]);
        end
        if(TState == 1 && Auto_Wait_t1 == 1'b0) begin
          DO <= BusB;
          if(I_RLD == 1'b1) begin
            DO[3:0] <= BusA[3:0];
            DO[7:4] <= BusB[3:0];
          end
          if(I_RRD == 1'b1) begin
            DO[3:0] <= BusB[7:4];
            DO[7:4] <= BusA[3:0];
          end
        end
        if(T_Res == 1'b1) begin
          Read_To_Reg_r[3:0] <= Set_BusA_To;
          Read_To_Reg_r[4] <= Read_To_Reg;
          if(Read_To_Acc == 1'b1) begin
            Read_To_Reg_r[3:0] <= 4'b0111;
            Read_To_Reg_r[4] <= 1'b1;
          end
        end
        if(TState == 1 && I_BT == 1'b1) begin
          F[Flag_X] <= ALU_Q[3];
          F[Flag_Y] <= ALU_Q[1];
          F[Flag_H] <= 1'b0;
          F[Flag_N] <= 1'b0;
        end
        if(I_BC == 1'b1 || I_BT == 1'b1) begin
          F[Flag_P] <= IncDecZ;
        end
        if((TState == 1 && Save_ALU_r == 1'b0 && Auto_Wait_t1 == 1'b0) || (Save_ALU_r == 1'b1 && ALU_OP_r != 4'b0111)) begin
          case(Read_To_Reg_r)
          5'b10111 : begin
            ACC <= Save_Mux;
          end
          5'b10110 : begin
            DO <= Save_Mux;
          end
          5'b11000 : begin
            SP[7:0] <= Save_Mux;
          end
          5'b11001 : begin
            SP[15:8] <= Save_Mux;
          end
          5'b11011 : begin
            F <= Save_Mux;
          end
          default : begin
          end
          endcase
          if(XYbit_undoc == 1'b1) begin
            DO <= ALU_Q;
          end
        end
      end
    end
  end
  //-------------------------------------------------------------------------
  //
  // BC('), DE('), HL('), IX and IY
  //
  //-------------------------------------------------------------------------
  always @(posedge CLK_n) begin
    if(ClkEn == 1'b1) begin
      // Bus A / Write
      RegAddrA_r <= {Alternate,Set_BusA_To[2:1]};
      if(XY_Ind == 1'b0 && XY_State != 2'b00 && Set_BusA_To[2:1] == 2'b10) begin
        RegAddrA_r <= {XY_State[1],2'b11};
      end
      // Bus B
      RegAddrB_r <= {Alternate,Set_BusB_To[2:1]};
      if(XY_Ind == 1'b0 && XY_State != 2'b00 && Set_BusB_To[2:1] == 2'b10) begin
        RegAddrB_r <= {XY_State[1],2'b11};
      end
      // Address from register
      RegAddrC <= {Alternate,Set_Addr_To[1:0]};
      // Jump (HL), LD SP,HL
      if((JumpXY == 1'b1 || LDSPHL == 1'b1)) begin
        RegAddrC <= {Alternate,2'b10};
      end
      if(((JumpXY == 1'b1 || LDSPHL == 1'b1) && XY_State != 2'b00) || (MCycle == 3'b110)) begin
        RegAddrC <= {XY_State[1],2'b11};
      end
      if(I_DJNZ == 1'b1 && Save_ALU_r == 1'b1 && Mode < 2) begin
        IncDecZ <= F_Out[Flag_Z];
      end
      if((TState == 2 || (TState == 3 && MCycle == 3'b001)) && IncDec_16[2:0] == 3'b100) begin
        if(ID16 == 0) begin
          IncDecZ <= 1'b0;
        end
        else begin
          IncDecZ <= 1'b1;
        end
      end
      RegBusA_r <= RegBusA;
    end
  end
  assign RegAddrA = (TState == 2 || (TState == 3 && MCycle == 3'b001 && IncDec_16[2] == 1'b1)) && XY_State == 2'b00 ? {Alternate,IncDec_16[1:0]} : (TState == 2 || (TState == 3 && MCycle == 3'b001 && IncDec_16[2] == 1'b1)) && IncDec_16[1:0] == 2'b10 ? {XY_State[1],2'b11} : ExchangeDH == 1'b1 && TState == 3 ? {Alternate,2'b10} : ExchangeDH == 1'b1 && TState == 4 ? {Alternate,2'b01} : RegAddrA_r;
  assign RegAddrB = ExchangeDH == 1'b1 && TState == 3 ? {Alternate,2'b01} : RegAddrB_r;
  assign ID16 = IncDec_16[3] == 1'b1 ? (RegBusA) - 1 : (RegBusA) + 1;
  always @(Save_ALU_r, Auto_Wait_t1, ALU_OP_r, Read_To_Reg_r, ExchangeDH, IncDec_16, MCycle, TState, Wait_n) begin
    RegWEH <= 1'b0;
    RegWEL <= 1'b0;
    if((TState == 1 && Save_ALU_r == 1'b0 && Auto_Wait_t1 == 1'b0) || (Save_ALU_r == 1'b1 && ALU_OP_r != 4'b0111)) begin
      case(Read_To_Reg_r)
      5'b10000,5'b10001,5'b10010,5'b10011,5'b10100,5'b10101 : begin
        RegWEH <=  ~Read_To_Reg_r[0];
        RegWEL <= Read_To_Reg_r[0];
      end
      default : begin
      end
      endcase
    end
    if(ExchangeDH == 1'b1 && (TState == 3 || TState == 4)) begin
      RegWEH <= 1'b1;
      RegWEL <= 1'b1;
    end
    if(IncDec_16[2] == 1'b1 && ((TState == 2 && Wait_n == 1'b1 && MCycle != 3'b001) || (TState == 3 && MCycle == 3'b001))) begin
      case(IncDec_16[1:0])
      2'b00,2'b01,2'b10 : begin
        RegWEH <= 1'b1;
        RegWEL <= 1'b1;
      end
      default : begin
      end
      endcase
    end
  end
  always @(Save_Mux, RegBusB, RegBusA_r, ID16, ExchangeDH, IncDec_16, MCycle, TState, Wait_n) begin
    RegDIH <= Save_Mux;
    RegDIL <= Save_Mux;
    if(ExchangeDH == 1'b1 && TState == 3) begin
      RegDIH <= RegBusB[15:8];
      RegDIL <= RegBusB[7:0];
    end
    if(ExchangeDH == 1'b1 && TState == 4) begin
      RegDIH <= RegBusA_r[15:8];
      RegDIL <= RegBusA_r[7:0];
    end
    if(IncDec_16[2] == 1'b1 && ((TState == 2 && MCycle != 3'b001) || (TState == 3 && MCycle == 3'b001))) begin
      RegDIH <= ID16[15:8];
      RegDIL <= ID16[7:0];
    end
  end
  T80_Reg Regs(
      .Clk(CLK_n),
    .CEN(ClkEn),
    .WEH(RegWEH),
    .WEL(RegWEL),
    .AddrA(RegAddrA),
    .AddrB(RegAddrB),
    .AddrC(RegAddrC),
    .DIH(RegDIH),
    .DIL(RegDIL),
    .DOAH(RegBusA[15:8]),
    .DOAL(RegBusA[7:0]),
    .DOBH(RegBusB[15:8]),
    .DOBL(RegBusB[7:0]),
    .DOCH(RegBusC[15:8]),
    .DOCL(RegBusC[7:0]));
  //-------------------------------------------------------------------------
  //
  // Buses
  //
  //-------------------------------------------------------------------------
  always @(posedge CLK_n) begin
    if(ClkEn == 1'b1) begin
      case(Set_BusB_To)
      4'b0111 : begin
        BusB <= ACC;
      end
      4'b0000,4'b0001,4'b0010,4'b0011,4'b0100,4'b0101 : begin
        if(Set_BusB_To[0] == 1'b1) begin
          BusB <= RegBusB[7:0];
        end
        else begin
          BusB <= RegBusB[15:8];
        end
      end
      4'b0110 : begin
        BusB <= DI_Reg;
      end
      4'b1000 : begin
        BusB <= SP[7:0];
      end
      4'b1001 : begin
        BusB <= SP[15:8];
      end
      4'b1010 : begin
        BusB <= 8'b00000001;
      end
      4'b1011 : begin
        BusB <= F;
      end
      4'b1100 : begin
        BusB <= PC[7:0];
      end
      4'b1101 : begin
        BusB <= PC[15:8];
      end
      4'b1110 : begin
        BusB <= 8'b00000000;
      end
      default : begin
        BusB <= 8'b--------;
      end
      endcase
      case(Set_BusA_To)
      4'b0111 : begin
        BusA <= ACC;
      end
      4'b0000,4'b0001,4'b0010,4'b0011,4'b0100,4'b0101 : begin
        if(Set_BusA_To[0] == 1'b1) begin
          BusA <= RegBusA[7:0];
        end
        else begin
          BusA <= RegBusA[15:8];
        end
      end
      4'b0110 : begin
        BusA <= DI_Reg;
      end
      4'b1000 : begin
        BusA <= SP[7:0];
      end
      4'b1001 : begin
        BusA <= SP[15:8];
      end
      4'b1010 : begin
        BusA <= 8'b00000000;
      end
      default : begin
        BusB <= 8'b--------;
      end
      endcase
      if(XYbit_undoc == 1'b1) begin
        BusA <= DI_Reg;
        BusB <= DI_Reg;
      end
    end
  end
  //-------------------------------------------------------------------------
  //
  // Generate external control signals
  //
  //-------------------------------------------------------------------------
  always @(posedge RESET_n, posedge CLK_n) begin
    if(RESET_n == 1'b0) begin
      RFSH_n <= 1'b1;
    end else begin
      if(CEN == 1'b1) begin
        if(MCycle == 3'b001 && ((TState == 2 && Wait_n == 1'b1) || TState == 3)) begin
          RFSH_n <= 1'b0;
        end
        else begin
          RFSH_n <= 1'b1;
        end
      end
    end
  end
  assign MC = MCycle;
  assign TS = TState;
  assign DI_Reg = DI;
  assign HALT_n =  ~Halt_FF;
  assign BUSAK_n =  ~BusAck;
  assign IntCycle_n =  ~IntCycle;
  assign IntE = IntE_FF1;
  assign IORQ = IORQ_i;
  assign Stop = I_DJNZ;
  //-----------------------------------------------------------------------
  //
  // Syncronise inputs
  //
  //-----------------------------------------------------------------------
  always @(posedge RESET_n, posedge CLK_n) begin : P1
    reg OldNMI_n;
    if(RESET_n == 1'b0) begin
      BusReq_s <= 1'b0;
      INT_s <= 1'b0;
      NMI_s <= 1'b0;
      OldNMI_n = 1'b0;
    end else begin
      if(CEN == 1'b1) begin
        BusReq_s <=  ~BUSRQ_n;
        INT_s <=  ~INT_n;
        if(NMICycle == 1'b1) begin
          NMI_s <= 1'b0;
        end
        else if(NMI_n == 1'b0 && OldNMI_n == 1'b1) begin
          NMI_s <= 1'b1;
        end
        OldNMI_n = NMI_n;
      end
    end
  end
  //-----------------------------------------------------------------------
  //
  // Main state machine
  //
  //-----------------------------------------------------------------------
  always @(posedge RESET_n, posedge CLK_n) begin
    if(RESET_n == 1'b0) begin
      MCycle <= 3'b001;
      TState <= 3'b000;
      Pre_XY_F_M <= 3'b000;
      Halt_FF <= 1'b0;
      BusAck <= 1'b0;
      NMICycle <= 1'b0;
      IntCycle <= 1'b0;
      IntE_FF1 <= 1'b0;
      IntE_FF2 <= 1'b0;
      No_BTR <= 1'b0;
      Auto_Wait_t1 <= 1'b0;
      Auto_Wait_t2 <= 1'b0;
      M1_n <= 1'b1;
    end else begin
      if(CEN == 1'b1) begin
        if(T_Res == 1'b1) begin
          Auto_Wait_t1 <= 1'b0;
        end
        else begin
          Auto_Wait_t1 <= Auto_Wait | IORQ_i;
        end
        Auto_Wait_t2 <= Auto_Wait_t1;
        No_BTR <= (I_BT & ( ~IR[4] |  ~F[Flag_P])) | (I_BC & ( ~IR[4] | F[Flag_Z] |  ~F[Flag_P])) | (I_BTR & ( ~IR[4] | F[Flag_Z]));
        if(TState == 2) begin
          if(SetEI == 1'b1) begin
            IntE_FF1 <= 1'b1;
            IntE_FF2 <= 1'b1;
          end
          if(I_RETN == 1'b1) begin
            IntE_FF1 <= IntE_FF2;
          end
        end
        if(TState == 3) begin
          if(SetDI == 1'b1) begin
            IntE_FF1 <= 1'b0;
            IntE_FF2 <= 1'b0;
          end
        end
        if(IntCycle == 1'b1 || NMICycle == 1'b1) begin
          Halt_FF <= 1'b0;
        end
        if(MCycle == 3'b001 && TState == 2 && Wait_n == 1'b1 && IntCycle == 1'b0) begin
          // by Fabio: Fix IM2 timing
          M1_n <= 1'b1;
        end
        if(MCycle == 3'b001 && TState == 3 && Wait_n == 1'b1 && IntCycle == 1'b1) begin
          // by Fabio: Fix IM2 timing
          M1_n <= 1'b1;
        end
        if(BusReq_s == 1'b1 && BusAck == 1'b1) begin
        end
        else begin
          BusAck <= 1'b0;
          if(TState == 2 && Wait_n == 1'b0) begin
          end
          else if(T_Res == 1'b1) begin
            if(Halt == 1'b1) begin
              Halt_FF <= 1'b1;
            end
            if(BusReq_s == 1'b1) begin
              BusAck <= 1'b1;
            end
            else begin
              TState <= 3'b001;
              if(NextIs_XY_Fetch == 1'b1) begin
                MCycle <= 3'b110;
                Pre_XY_F_M <= MCycle;
                if(IR == 8'b00110110 && Mode == 0) begin
                  Pre_XY_F_M <= 3'b010;
                end
              end
              else if((MCycle == 3'b111) || (MCycle == 3'b110 && Mode == 1 && ISet != 2'b01)) begin
                MCycle <= (Pre_XY_F_M) + 1;
              end
              else if((MCycle == MCycles) || No_BTR == 1'b1 || (MCycle == 3'b010 && I_DJNZ == 1'b1 && IncDecZ == 1'b1)) begin
                M1_n <= 1'b0;
                MCycle <= 3'b001;
                IntCycle <= 1'b0;
                NMICycle <= 1'b0;
                if(NMI_s == 1'b1 && Prefix == 2'b00) begin
                  NMICycle <= 1'b1;
                  IntE_FF1 <= 1'b0;
                end
                else if((IntE_FF1 == 1'b1 && INT_s == 1'b1) && Prefix == 2'b00 && SetEI == 1'b0) begin
                  IntCycle <= 1'b1;
                  IntE_FF1 <= 1'b0;
                  IntE_FF2 <= 1'b0;
                end
              end
              else begin
                MCycle <= (MCycle) + 1;
              end
            end
          end
          else begin
            if(!((Auto_Wait == 1'b1 && Auto_Wait_t2 == 1'b0) || (IOWait == 1 && IORQ_i == 1'b1 && Auto_Wait_t1 == 1'b0))) begin
              TState <= TState + 1;
            end
          end
        end
        if(TState == 0) begin
          M1_n <= 1'b0;
        end
      end
    end
  end
  always @(IntCycle, NMICycle, MCycle) begin
    Auto_Wait <= 1'b0;
    if(IntCycle == 1'b1 || NMICycle == 1'b1) begin
      if(MCycle == 3'b001) begin
        Auto_Wait <= 1'b1;
      end
    end
  end
endmodule

