reg [7:0] reg_b;
wire [7:0] shift_out;
wire [7:0] half_adder_out;

// Instantiate shift register and half adder
shift_register sr(clk, a, reg_a, shift_out);
half_adder ha(clk, reg_a[0], b[0], half_adder_out[0]);

// Connect half adder to shift register
genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : adder_loop
        half_adder ha(clk, reg_a[i], b[i], half_adder_out[i]);
        assign reg_a[i] = shift_out[i-1];
    end
endgenerate

// Instantiate 2-to-1 multiplexer
mux2to1 mux(shift_out[7], half_adder_out[7], sum);

endmodule

module parity_mux (
    input [7:0] in0,
    input [7:0] in1,
    input sel,
    output reg [8:0] out
);

    // 8-bit odd parity checker
    wire [7:0] in_xor = in0 ^ in1;
    wire odd_parity = ^in_xor;

    // 2-to-1 multiplexer
    always @(*) begin
        if (sel == 1'b0) begin
            out[8:1] = in0;
        end else begin
            out[8:1] = in1;
        end
    end

    // Parity bit computation
    always @(*) begin
        if (odd_parity == 1'b1) begin
            out[0] = 1'b1;
        end else begin
            out[0] = 1'b0;
        end
    end

endmodule

module booth_multiplier (
    input clk,
    input reset,
    input [3:0] DATA_IN_A,
    input [2:0] DATA_IN_B,
    output reg [6:0] PRODUCT_OUT
);

    reg [4:0] A;
    reg [3:0] S;
    reg [2:0] P;
    reg [1:0] count;
    reg [3:0] temp;

    always @(posedge clk) begin
        if (reset) begin
            A <= 0;
            S <= 0;
            P <= 0;
            count <= 0;
        end else begin
            temp <= {DATA_IN_A, 2'b0};
            if (count == 0) begin
                S <= DATA_IN_B;
                P <= 0;
            end else begin
                if (S[1:0] == 2'b01) begin
                    P <= P + temp;
                end else if (S[1:0] == 2'b10) begin
                    P <= P - temp;
                end
                S <= {S[1], S[0], S[2]};
            end
            count <= count + 1;
        end
    end

    assign PRODUCT_OUT = P[6:0];

endmodule

module magnitude_comparator(A, B, EQ, GT, LT);
