module unidade_controle_transmissao(
input wire liga,
input wire enviar,
input wire reset,
input wire clock,
input wire CTS,
output reg DTR,
output reg RTS,
output reg enable_transmissao,
output wire envioOk,
output reg [1:0] s_estado
);
// depuracao
parameter [1:0]
  inicial = 0,
  ligado = 1,
  transmissao = 2,
  espera = 3;
reg [1:0] estado;
  assign envioOk = CTS;
  always @(posedge clock, posedge estado, posedge reset, posedge liga, posedge enviar) begin
    if(reset == 1'b1) begin
      estado <= inicial;
    end else begin
      case(estado)
      inicial : begin
        if(liga == 1'b1) begin
          estado <= ligado;
        end
      end
      ligado : begin
        if(liga == 1'b1) begin
          if(enviar == 1'b1) begin
            estado <= espera;
          end
        end
        else begin
          estado <= inicial;
        end
      end
      espera : begin
        if(enviar == 1'b1) begin
          if(CTS == 1'b1) begin
            estado <= transmissao;
          end
        end
        else begin
          estado <= ligado;
        end
      end
      transmissao : begin
        if(enviar == 1'b0) begin
          estado <= ligado;
        end
      end
      endcase
    end
  end
  always @(estado) begin
    case(estado)
    inicial : begin
      s_estado <= 2'b00;
      DTR <= 1'b0;
      RTS <= 1'b0;
      enable_transmissao <= 1'b0;
    end
    ligado : begin
      s_estado <= 2'b01;
      DTR <= 1'b1;
      RTS <= 1'b0;
      enable_transmissao <= 1'b0;
    end
    espera : begin
      s_estado <= 2'b10;
      DTR <= 1'b1;
      RTS <= 1'b1;
      enable_transmissao <= 1'b0;
    end
    transmissao : begin
      s_estado <= 2'b11;
      DTR <= 1'b1;
      RTS <= 1'b1;
      enable_transmissao <= 1'b1;
    end
    endcase
  end
endmodule

