module debounce(
input wire clk,
input wire din,
output reg dout
);
  always @(posedge clk) begin : P1
    reg [31:0] count = 0;
    reg value = 1'b0;
    if(value != din) begin
      value = din;
      count = 0;
    end
    else begin
      count = count + 1;
      if(count == 1000000) begin
        dout <= # 1 value;
      end
    end
  end
endmodule

module shift_register(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);

    reg [3:0] stage1, stage2, stage3, stage4;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            stage1 <= 4'b0000;
            stage2 <= 4'b0000;
            stage3 <= 4'b0000;
            stage4 <= 4'b0000;
            q <= 4'b0000;
        end else if (load) begin
            stage1 <= data[0];
            stage2 <= data[1];
            stage3 <= data[2];
            stage4 <= data[3];
            q <= data;
        end else if (ena) begin
            stage1 <= q[0];
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
            q <= {stage4, q[3:1]};
        end
    end

endmodule

