module psdos(
    input Rx,
    input CLKOUT,
    output reg Rx_error,
    output [7:0] DATA,
    output reg DONE
);

    reg [8:0] regis;
    reg [7:0] regis0;
    reg [3:0] i;
    reg [3:0] j;
    reg init;

    initial begin
        i = 0;
        j = 0;
        init = 0;
        regis = 0;
        regis0 = 0;
        Rx_error = 0;
        DONE = 0;
    end

    always @(posedge CLKOUT) begin
        if (!Rx && !i) begin
            init <= 1;
        end

        if (init) begin
            regis[i] <= Rx;
            i <= i + 1;

            if (regis[i] && (i < 8)) begin
                j <= j + 1;
            end
        end

        if (i == 9) begin
            if ((!(j % 2) && regis[8]) || ((j % 2) && !regis[8])) begin
                Rx_error <= 0;
                regis0 <= {regis[7:0]};
                DONE <= 1;
            end
            else begin
                Rx_error <= 1;
                regis0 <= 0;
                DONE <= 0;
            end

            j <= 0;
            i <= 0;
            init <= 0;
        end
    end

    assign DATA = regis0;

endmodule

module ALU(
input wire [7:0] alu_input_1,
input wire [7:0] alu_input_2,
output reg [7:0] alu_output,
input wire [7:0] alu_command,
inout reg busy,
input wire clk
);
// first ALU input ( 8 bit)
// second ALU input ( 8 bit)
// output signal of ALU ( 8 bit)
// command for ALU
// one bit signal that tells us if ALU is busy or not
// clock input
  always @(posedge clk) begin
    if(alu_command == 8'b00000001) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 + alu_input_2;
      // addition of input 
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000010) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 - alu_input_2;
      // substraction of input signals
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000011) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 & alu_input_2;
      // AND operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000100) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 | alu_input_2;
      // OR operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000101) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 ^ alu_input_2;
      // XOR operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000110) begin
      busy <= 1'b1;
      alu_output <=  ~alu_input_1;
      // NOT operation
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00000111) begin
      busy <= 1'b1;
      alu_output <= (alu_input_1) >> 1;
      //shift right
      busy <= 1'b0;
    end
    else if(alu_command == 8'b00001000) begin
      busy <= 1'b1;
      alu_output <= alu_input_1 + alu_input_1;
      //shift left
      busy <= 1'b0;
    end
  end
endmodule

