module increment_signed(A, CI, Z);
  input signed [15:0] A;
  input CI;
  output signed [16:0] Z;

  wire signed [15:0] A_abs;
  wire signed [15:0] A_abs_inverted;
  wire [16:0] Z_abs;
  wire [16:0] Z_abs_inverted;
  wire CO;

  // Convert A to its absolute value
  assign A_abs = (A < 0) ? (~A + 1) : A;

  // Set the carry-in signal based on the sign of A
  assign CO = (A < 0) ? 1'b1 : CI;

  // Increment the absolute value of A by 1
  ripple_carry_adder_16bit rca(.A(A_abs), .B(16'b1), .CI(CO), .S(Z_abs));

  // Convert the result back to its signed form
  assign Z_abs_inverted = (Z_abs == 17'b0) ? 17'b0 : (~Z_abs + 1);
  assign Z = (A < 0) ? Z_abs_inverted : Z_abs;

endmodule

module synchronous_double_port_ram
  (
   // Generic synchronous double-port RAM interface
   input clk_a, ce_a, clk_b, ce_b, we_b,
