module rx_path_header_extraction(
input wire clk,
input wire reset,
input wire [RECEIVER_DATA_WIDTH - 1:0] hext_in_data,
input wire hext_in_valid,
input wire hext_in_last,
input wire [TIMESTAMP_WIDTH - 1:0] hext_in_timestamp_cnt,
output wire [DEST_ADDR_WIDTH - 1:0] hext_out_dest,
output wire hext_out_vlan_enable,
output wire [VLAN_PRIO_WIDTH - 1:0] hext_out_vlan_prio,
output wire hext_out_valid,
output wire [TIMESTAMP_WIDTH - 1:0] hext_out_timestamp,
input wire hext_out_ready
);
parameter [31:0] RECEIVER_DATA_WIDTH;
parameter [31:0] DEST_ADDR_WIDTH;
parameter [31:0] VLAN_PRIO_WIDTH;
parameter [31:0] TIMESTAMP_WIDTH;
// input interface
// output interface
parameter DEST_ADDR_WIDTH_BYTE = DEST_ADDR_WIDTH / 8;
parameter SOURCE_ADDR_WIDTH = 6;
parameter UPPER_DEST_ADDRESS = SOURCE_ADDR_WIDTH;
parameter UPPER_SOURCE_ADDRESS = UPPER_DEST_ADDRESS + SOURCE_ADDR_WIDTH;
parameter CNT_WIDTH = 5;  // ld ethernet_header size = ld 18
parameter VLAN_TPID1 = 8'h81;
parameter VLAN_TPID2 = 8'h00;
parameter TPID_UPPER = 7;
parameter TPID_LOWER = 5;  // extraction header state machine
parameter [2:0]
  IDLE = 0,
  DEST_ADDR = 1,
  SOURCE_ADDR = 2,
  TYPE_LENGTH1 = 3,
  TYPE_LENGTH2 = 4,
  VLAN_PRIO = 5,
  HANDSHAKE = 6,
  WAIT_EOF = 7;
reg [2:0] cur_state;
reg [2:0] nxt_state;  // state machine signals
reg update_cnt_sig = 1'b0;
reg reset_cnt_sig = 1'b0;
reg read_dest_sig = 1'b0;
reg vlan_frame_sig = 1'b0;
reg no_vlan_frame_sig = 1'b0;
reg read_vlan_prio_sig = 1'b0;
reg valid_out_sig = 1'b0;
reg read_timestamp_sig = 1'b0;  // process registers
reg [DEST_ADDR_WIDTH - 1:0] dest_reg = 1'b0;  // contains mac destination address
reg vlan_frame_reg = 1'b0;  // indicates whether the current frame is a vlan frame
reg [VLAN_PRIO_WIDTH - 1:0] vlan_prio_reg = 1'b0;  // contains the vlan priority
reg valid_reg = 1'b0;  // indicates whether output is valid or not
reg [TIMESTAMP_WIDTH - 1:0] timestamp_reg;
reg [CNT_WIDTH - 1:0] cnt = 1'b0;  // frame byte counter
  // next state logic
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      cur_state <= IDLE;
    end
    else begin
      cur_state <= nxt_state;
    end
  end
  // Decode next state, combinitorial logic
  always @(cur_state, hext_in_valid, cnt, hext_out_ready, hext_in_data, hext_in_last) begin
    nxt_state <= IDLE;
    update_cnt_sig <= 1'b0;
    reset_cnt_sig <= 1'b0;
    read_dest_sig <= 1'b0;
    vlan_frame_sig <= 1'b0;
    no_vlan_frame_sig <= 1'b0;
    read_vlan_prio_sig <= 1'b0;
    valid_out_sig <= 1'b0;
    read_timestamp_sig <= 1'b0;
    case(cur_state)
    IDLE : begin
      // waiting for a frame
      if(hext_in_valid == 1'b1 && hext_in_last == 1'b0) begin
        nxt_state <= DEST_ADDR;
        update_cnt_sig <= 1'b1;
        // cnt_p
        read_dest_sig <= 1'b1;
        // dest_mac_p
        read_timestamp_sig <= 1'b1;
        // read_timestamp_p
      end
    end
    DEST_ADDR : begin
      // extracting the destination mac address
      if(cnt == (UPPER_DEST_ADDRESS - 1) && hext_in_valid == 1'b1) begin
        nxt_state <= SOURCE_ADDR;
      end
      else begin
        nxt_state <= DEST_ADDR;
      end
      if(hext_in_valid == 1'b1) begin
        read_dest_sig <= 1'b1;
        // dest_mac_p
        update_cnt_sig <= 1'b1;
        // cnt_p
      end
    end
    SOURCE_ADDR : begin
      // 6 bytes of source mac address
      if(cnt == (UPPER_SOURCE_ADDRESS - 1) && hext_in_valid == 1'b1) begin
        nxt_state <= TYPE_LENGTH1;
      end
      else begin
        nxt_state <= SOURCE_ADDR;
      end
      if(hext_in_valid == 1'b1) begin
        update_cnt_sig <= 1'b1;
        // cnt_p
      end
    end
    TYPE_LENGTH1 : begin
      // first length/type byte, check for vlan frame
      if(hext_in_valid == 1'b1) begin
        if(hext_in_data == VLAN_TPID1) begin
          nxt_state <= TYPE_LENGTH2;
        end
        else begin
          no_vlan_frame_sig <= 1'b1;
          // vlan_frame_p
          valid_out_sig <= 1'b1;
          // output_handshake_p
          nxt_state <= HANDSHAKE;
        end
      end
      else begin
        nxt_state <= TYPE_LENGTH1;
      end
    end
    TYPE_LENGTH2 : begin
      // second length/type byte, check for vlan frame
      if(hext_in_valid == 1'b1) begin
        if(hext_in_data == VLAN_TPID2) begin
          nxt_state <= VLAN_PRIO;
          vlan_frame_sig <= 1'b1;
          // vlan_frame_p
        end
        else begin
          no_vlan_frame_sig <= 1'b1;
          // vlan_frame_p
          valid_out_sig <= 1'b1;
          // output_handshake_p
          nxt_state <= HANDSHAKE;
        end
      end
      else begin
        nxt_state <= TYPE_LENGTH2;
      end
    end
    VLAN_PRIO : begin
      // extract vlan priority field
      if(hext_in_valid == 1'b1) begin
        nxt_state <= HANDSHAKE;
        valid_out_sig <= 1'b1;
        // output_handshake_p
        read_vlan_prio_sig <= 1'b1;
        // vlan_prio_p
      end
      else begin
        nxt_state <= VLAN_PRIO;
      end
    end
    HANDSHAKE : begin
      // send output data to next layer
      if(hext_out_ready == 1'b1) begin
        nxt_state <= WAIT_EOF;
        reset_cnt_sig <= 1'b1;
        // cnt_p
      end
      else begin
        nxt_state <= HANDSHAKE;
        valid_out_sig <= 1'b1;
        // output_handshake_p
      end
    end
    WAIT_EOF : begin
      // wait for last byte of current frame
      if(hext_in_last == 1'b1) begin
        nxt_state <= IDLE;
      end
      else begin
        nxt_state <= WAIT_EOF;
      end
    end
    endcase
  end
  // header bytes counter
  always @(posedge clk) begin
    if(reset == 1'b1 || reset_cnt_sig == 1'b1) begin
      cnt <= {((CNT_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      cnt <= cnt;
      if(update_cnt_sig == 1'b1) begin
        cnt <= cnt + 1;
      end
    end
  end
  // write the destination address of the current frame to an internal register
  always @(posedge clk) begin : P1
    reg [31:0] remaining_dest_bytes;
    if(reset == 1'b1) begin
      dest_reg <= {((DEST_ADDR_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      dest_reg <= dest_reg;
      if(read_dest_sig == 1'b1) begin
        remaining_dest_bytes = DEST_ADDR_WIDTH_BYTE - (cnt);
        dest_reg[remaining_dest_bytes * 8 - 1:remaining_dest_bytes * 8 - RECEIVER_DATA_WIDTH] <= hext_in_data;
      end
    end
  end
  // store the timestamp for incoming messages
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      timestamp_reg <= {((TIMESTAMP_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      timestamp_reg <= timestamp_reg;
      if(read_timestamp_sig == 1'b1) begin
        timestamp_reg <= hext_in_timestamp_cnt;
      end
    end
  end
  // write to an internal register if the current frame is a vlan frame
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      vlan_frame_reg <= 1'b0;
    end
    else begin
      vlan_frame_reg <= vlan_frame_reg;
      if(no_vlan_frame_sig == 1'b1) begin
        vlan_frame_reg <= 1'b0;
      end
      else if(vlan_frame_sig == 1'b1) begin
        vlan_frame_reg <= 1'b1;
      end
    end
  end
  // write the vlan priority to an internal register
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      vlan_prio_reg <= {((VLAN_PRIO_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      vlan_prio_reg <= vlan_prio_reg;
      if(read_vlan_prio_sig == 1'b1) begin
