      valid_reg <= 1'b0;
      if(valid_out_sig == 1'b1) begin
        valid_reg <= 1'b1;
      end
    end
  end
  assign hext_out_dest = dest_reg;
  assign hext_out_vlan_enable = vlan_frame_reg;
  assign hext_out_vlan_prio = vlan_prio_reg;
