module spike_filter(
input wire clock,
input wire pin_in,
output reg pin_out
);
parameter [31:0] g_stable_time=8;
reg pin_c;
reg [31:0] cnt = (g_stable_time - 1) / 2;
  always @(posedge clock) begin
    pin_c <= pin_in;
    if(pin_c == 1'b0) begin
      if(cnt == 0) begin
        pin_out <= 1'b0;
      end
      else begin
        cnt <= cnt - 1;
      end
    end
    else begin
      if(cnt == (g_stable_time - 1)) begin
        pin_out <= 1'b1;
      end
      else begin
        cnt <= cnt + 1;
      end
    end
  end
endmodule

