reg [2:0] status_reg;
reg [3:0] ECC_reg;
  // Connect the registers to the outputs
  always @(voted_data_reg, status_reg, ECC_reg) begin
    voted_data_out <= voted_data_reg;
    status_out <= status_reg;
    ECC_out <= ECC_reg;
