module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input select,     // Select input to choose between counter and multiplexer
    input [1023:0] in_mux, // 256 4-bit inputs packed into a single 1024-bit input vector
    output [3:0] q); // 4-bit output from the active module

    // Counter module
    reg [3:0] count;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0;
        end else if (count == 4'b1111) begin
            count <= 4'b0;
        end else begin
            count <= count + 1;
        end
    end

    // Multiplexer module
    wire [3:0] mux_out;
    reg [7:0] select_reg;
    always @(posedge clk) begin
        if (reset) begin
            select_reg <= 8'b0;
        end else begin
            select_reg <= select_reg + 1;
        end
    end

    // Binary tree architecture for the multiplexer
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : mux_tree
            if (i == 0) begin
                assign mux_out = in_mux[select_reg[7:6]*16 + select_reg[5:2]*4 + select_reg[1:0]];
            end else begin
                wire [3:0] mux_left, mux_right;
                assign mux_left = mux_tree[i-1].mux_out;
                assign mux_right = mux_tree[i-1].mux_out;
                assign mux_out = (select_reg[7-i] == 1'b0) ? mux_left : mux_right;
            end
        end
    endgenerate

    // Control logic module to enable either the counter or the multiplexer
    always @(*) begin
        if (select == 1'b0) begin
            q = count | 4'b0000;
        end else begin
            q = mux_out | count;
        end
    end

endmodule

