    fifo_clear,
    fifo_rd,
    rst_n,
    t_dat,
    wr_rfifo,

    // outputs:
    fifo_EF,
    fifo_rdata,
    rfifo_full,
    rfifo_used
);

    output fifo_EF;
    output [7:0] fifo_rdata;
    output rfifo_full;
