    reg [5:0] fifo_head;
    reg [5:0] fifo_tail;
    wire fifo_empty = (fifo_used == 0);
    wire fifo_full = (fifo_used == 64);

    assign fifo_EF = fifo_empty || fifo_full;
    assign fifo_rdata = fifo_mem[fifo_tail];
    assign rfifo_full = fifo_full;
    assign rfifo_used = fifo_used;

