        if (!rst_n) begin
            fifo_head <= 6'd0;
            fifo_tail <= 6'd0;
            fifo_used <= 6'd0;
        end else begin
            if (fifo_clear) begin
                fifo_head <= 6'd0;
                fifo_tail <= 6'd0;
                fifo_used <= 6'd0;
            end else begin
                if (wr_rfifo && !fifo_full) begin
                    fifo_mem[fifo_head] <= t_dat;
                    fifo_head <= fifo_head + 1;
                    fifo_used <= fifo_used + 1;
                end
                if (fifo_rd && !fifo_empty) begin
                    fifo_tail <= fifo_tail + 1;
                    fifo_used <= fifo_used - 1;
                end
            end
        end
    end

endmodule

