module add_sub_overflow (
    input [3:0] A,
    input [3:0] B,
    input Sub,
    output [3:0] Sum,
    output Overflow
);

    reg [3:0] temp_sum;
    reg temp_overflow;

    always @(*) begin
        if (Sub == 1) begin
            temp_sum = A - B;
            if (A[3] == 1 && B[3] == 0 && temp_sum[3] == 0) begin
                temp_overflow = 1;
            end else if (A[3] == 0 && B[3] == 1 && temp_sum[3] == 1) begin
                temp_overflow = 1;
            end else begin
                temp_overflow = 0;
            end
        end else begin
            temp_sum = A + B;
            if (A[3] == 0 && B[3] == 0 && temp_sum[3] == 1) begin
                temp_overflow = 1;
            end else if (A[3] == 1 && B[3] == 1 && temp_sum[3] == 0) begin
                temp_overflow = 1;
            end else begin
                temp_overflow = 0;
            end
        end
    end

    assign Sum = temp_sum;
    assign Overflow = temp_overflow;

endmodule

module fifo_buffer (
  input clk,
  input rst,
  input wr_en,
  input rd_en,
  input [7:0] data_in,
  output [7:0] data_out,
  output full,
  output empty
);

  localparam DEPTH = 8;

  reg [7:0] buffer [DEPTH-1:0];
  reg [2:0] wr_ptr;
  reg [2:0] rd_ptr;
  reg full;
  reg empty;

  always @(posedge clk) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      full <= 0;
      empty <= 1;
    end
    else begin
      if (wr_en && !full) begin
        buffer[wr_ptr] <= data_in;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == DEPTH) begin
          wr_ptr <= 0;
        end
        if (wr_ptr == rd_ptr) begin
          full <= 1;
        end
        empty <= 0;
      end
      if (rd_en && !empty) begin
        data_out <= buffer[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == DEPTH) begin
          rd_ptr <= 0;
        end
        if (rd_ptr == wr_ptr) begin
          empty <= 1;
        end
        full <= 0;
      end
    end
  end

endmodule

module tri_mode_ethernet_mac_0_example_design_resets(
input wire s_axi_aclk,
input wire gtx_clk,
input wire glbl_rst,
input wire reset_error,
input wire rx_reset,
input wire tx_reset,
input wire dcm_locked,
output wire glbl_rst_intn,
output reg gtx_resetn,
output reg s_axi_resetn,
output wire phy_resetn,
output reg chk_resetn
);
// clocks
// asynchronous resets
// synchronous reset outputs
//----------------------------------------------------------------------------
// Component declaration for the reset synchroniser
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
// Component declaration for the synchroniser
//----------------------------------------------------------------------------
// define internal signals
reg s_axi_pre_resetn = 1'b0;
wire s_axi_reset_int;
wire combined_reset;
reg gtx_pre_resetn = 1'b0;
wire gtx_clk_reset_int;
wire clear_checker;
reg chk_pre_resetn = 1'b0;
wire chk_reset_int;
wire dcm_locked_sync;
wire glbl_rst_int;
reg phy_resetn_int;
reg [5:0] phy_reset_count = 1'b0;
  //----------------------------------------------------------------------------
  // Synchronise the async dcm_locked into the gtx_clk clock domain
  //----------------------------------------------------------------------------
  tri_mode_ethernet_mac_0_sync_block dcm_sync(
      .clk(gtx_clk),
    .data_in(dcm_locked),
    .data_out(dcm_locked_sync));
  //----------------------------------------------------------------------------
  // Generate resets required for the fifo side signals etc
  //----------------------------------------------------------------------------
  // in each case the async reset is first captured and then synchronised
  //---------------
  // global reset
  tri_mode_ethernet_mac_0_reset_sync glbl_reset_gen(
      .clk(gtx_clk),
    .enable(dcm_locked_sync),
    .reset_in(glbl_rst),
    .reset_out(glbl_rst_int));
  assign glbl_rst_intn =  ~glbl_rst_int;
  //---------------
  // AXI-Lite reset
  tri_mode_ethernet_mac_0_reset_sync axi_lite_reset_gen(
      .clk(s_axi_aclk),
    .enable(phy_resetn_int),
    .reset_in(glbl_rst),
    .reset_out(s_axi_reset_int));
  // Create fully synchronous reset in the s_axi clock domain.
  always @(posedge s_axi_aclk) begin
    if(s_axi_reset_int == 1'b1) begin
      s_axi_pre_resetn <= 1'b0;
      s_axi_resetn <= 1'b0;
    end
    else begin
      s_axi_pre_resetn <= 1'b1;
      s_axi_resetn <= s_axi_pre_resetn;
    end
  end
  //---------------
  // gtx_clk reset
  assign combined_reset = glbl_rst | rx_reset | tx_reset;
  tri_mode_ethernet_mac_0_reset_sync gtx_reset_gen(
      .clk(gtx_clk),
    .enable(dcm_locked_sync),
    .reset_in(combined_reset),
    .reset_out(gtx_clk_reset_int));
  // Create fully synchronous reset in the gtx_clk domain.
  always @(posedge gtx_clk) begin
    if(gtx_clk_reset_int == 1'b1) begin
      gtx_pre_resetn <= 1'b0;
      gtx_resetn <= 1'b0;
    end
    else begin
      gtx_pre_resetn <= 1'b1;
      gtx_resetn <= gtx_pre_resetn;
    end
  end
  //---------------
  // data check reset
  assign clear_checker = glbl_rst | reset_error;
  tri_mode_ethernet_mac_0_reset_sync chk_reset_gen(
      .clk(gtx_clk),
    .enable(dcm_locked_sync),
    .reset_in(clear_checker),
    .reset_out(chk_reset_int));
  // Create fully synchronous reset in the gtx_clk domain.
  always @(posedge gtx_clk) begin
    if(chk_reset_int == 1'b1) begin
      chk_pre_resetn <= 1'b0;
      chk_resetn <= 1'b0;
    end
    else begin
      chk_pre_resetn <= 1'b1;
      chk_resetn <= chk_pre_resetn;
    end
  end
  //---------------
  // PHY reset
  // the phy reset output (active low) needs to be held for at least 10x25MHZ cycles
  // this is derived using the 125MHz available and a 6 bit counter
  always @(posedge gtx_clk) begin
    if(glbl_rst_int == 1'b1) begin
      phy_resetn_int <= 1'b0;
      phy_reset_count <= {6{1'b0}};
    end
    else begin
      if(phy_reset_count != 6'b111111) begin
        phy_reset_count <= phy_reset_count + 6'b000001;
      end
      else begin
        phy_resetn_int <= 1'b1;
      end
    end
  end
  assign phy_resetn = phy_resetn_int;
endmodule

module nonrestore_div #(
	parameter	NUMERATOR_WIDTH		= 64,
	parameter	DENOMINATOR_WIDTH	= 64
)(
	input										clk,
	input										clr,
	input		[NUMERATOR_WIDTH	- 1	: 0]	numer_in,
	input		[DENOMINATOR_WIDTH	- 1	: 0]	denom_in,
	output	reg	[NUMERATOR_WIDTH	- 1	: 0]	quot_out,
	output	reg	[DENOMINATOR_WIDTH	- 1	: 0]	rem_out,
	output	reg									rdy_out
);

// Define the states of the state machine
localparam	s0 = 4'b0001;
localparam	s1 = 4'b0010;
localparam	s2 = 4'b0100;
localparam	s3 = 4'b1000;

// Define the width of temporary variables
localparam	TMPVAR_WIDTH		= NUMERATOR_WIDTH + DENOMINATOR_WIDTH;
localparam	REM_ITER_MSB		= DENOMINATOR_WIDTH;
localparam	QUOT_MSB			= NUMERATOR_WIDTH - 1;

// Define the state variables
reg			[3						: 0]	state;
reg			[NUMERATOR_WIDTH	- 1	: 0]	numer;
reg			[DENOMINATOR_WIDTH	- 1	: 0]	denom;
reg			[DENOMINATOR_WIDTH		: 0]	denom_neg;
reg			[NUMERATOR_WIDTH	- 1	: 0]	quot;
reg			[DENOMINATOR_WIDTH	- 1 : 0]	rem;
reg			[DENOMINATOR_WIDTH		: 0]	rem_iter;
reg			[7						: 0]	count;

// Define the wires
wire		[DENOMINATOR_WIDTH		: 0]	rem_iter_shift;
wire		[NUMERATOR_WIDTH	- 1 : 0]	quot_shift;
wire		[DENOMINATOR_WIDTH		: 0]	rem_iter_sum;

// Define the combinational logic
assign		{rem_iter_shift, quot_shift} = {rem_iter, quot} << 1;
assign		rem_iter_sum = rem_iter_shift + (rem_iter[REM_ITER_MSB]) ? denom : denom_neg;

// Define the state machine
always @ (posedge clk or posedge clr)
begin
	if (clr) begin
		state		<= s0;
		rdy_out		<= 1'b0;
		numer		<= 0;
		denom		<= 0;
		denom_neg	<= 0;
		quot		<= 0;
		rem_iter	<= 0;
		rem			<= 0;
		count		<= 0;
	end
	else begin
		case (state)
			s0	: begin
				numer		<= numer_in;
				denom		<= denom_in;
				denom_neg	<= {1'b1,~denom_in} + 1;
				quot		<= numer_in;
				rem_iter	<= 0;
				count		<= 0;
				state		<= s1;
			end
			s1	: begin
				count		<= count + 1;
				quot[QUOT_MSB : 1]	<= quot_shift[QUOT_MSB : 1];
				rem_iter	<= rem_iter_sum;
				if (rem_iter_sum[REM_ITER_MSB]) begin
					quot[0] <= 0;
				end
				else begin
					quot[0] <= 1;
				end
				if (count == NUMERATOR_WIDTH - 1) begin
					state	<= s2;
				end
			end
			s2	: begin
				if (rem_iter[REM_ITER_MSB]) begin	// rem < 0
					rem 	<= rem_iter + denom;
				end
				else begin
					rem 	<= rem_iter;
				end
				state 		<= s3;
			end
			s3	: begin
				quot_out	<= quot;
				rem_out		<= rem;
				rdy_out		<= 1'b1;
			end
			default : begin
				state 		<= s0;
			end
		endcase
	end
end

endmodule

