module InternalROM(
input wire CLK,
input wire [16:0] ADDR,
output wire [7:0] DATA
);
reg basic_rom_enable;
reg kernal_rom_enable;
reg float_rom_enable;
reg sddos_rom_enable;
wire [7:0] kernal_data;
wire [7:0] basic_data;
wire [7:0] float_data;
wire [7:0] sddos_data;
  atombasic romc000(
      .CLK(CLK),
    .ADDR(ADDR[11:0]),
    .DATA(basic_data));
  atomfloat romd000(
      .CLK(CLK),
    .ADDR(ADDR[11:0]),
    .DATA(float_data));
  SDROM rome000(
      .CLK(CLK),
    .ADDR(ADDR[11:0]),
    .DATA(sddos_data));
  atomkernal romf000(
      .CLK(CLK),
    .ADDR(ADDR[11:0]),
    .DATA(kernal_data));
  always @(ADDR) begin
    // All regions normally de-selected
    sddos_rom_enable <= 1'b0;
    basic_rom_enable <= 1'b0;
    kernal_rom_enable <= 1'b0;
    float_rom_enable <= 1'b0;
    case(ADDR[15:12])
    4'hC : begin
