parameter a = 3; // constant used to generate the pseudo-random number
parameter c = 5; // constant used to generate the pseudo-random number

reg [n-1:0] shift_reg;

always @(posedge clock) begin
  if (reset) begin
    shift_reg <= seed;
  end else begin
