module FSMctrl(
input wire CLK,
input wire RST,
input wire ENTER,
input wire [1:0] Operacao,
output reg [1:0] Selecao,
output reg Enable_1,
output reg Enable_2
);
//ARCHITECTURE
parameter [2:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3,
  S4 = 4,
  S5 = 5,
  S6 = 6,
  S7 = 7;
reg [2:0] EA; reg [2:0] PE;
wire clock;
wire reset;
  assign clock = CLK;
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b0) begin
      EA <= S0;
    end else begin
      EA <= PE;
    end
  end
  always @(EA, ENTER, Operacao) begin
    case(EA)
    S0 : begin
      if(Enter == 1'b1) begin
        PE <= S0;
      end
      else begin
        PE <= S1;
      end
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b0;
    end
    S1 : begin
      if(Enter == 1'b0) begin
        PE <= S1;
      end
      else begin
        PE <= S2;
      end
      Enable_1 <= 1'b1;
      Enable_2 <= 1'b0;
    end
    S2 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b0;
      if(Operacao == 2'b00) begin
        PE <= S3;
      end
      else if(Operacao == 2'b01) begin
        PE <= S4;
      end
      else if(Operacao == 2'b10) begin
        PE <= S5;
      end
      else if(Operacao == 2'b11) begin
        PE <= S6;
      end
    end
    S3 : begin
      Selecao <= 2'b00;
      if(Enter == 1'b1) begin
        PE <= S3;
      end
      else begin
        PE <= S7;
      end
    end
    S4 : begin
      Selecao <= 2'b01;
      if(Enter == 1'b1) begin
        PE <= S4;
      end
      else begin
        PE <= S7;
      end
    end
    S5 : begin
      Selecao <= 2'b10;
      if(Enter == 1'b1) begin
        PE <= S5;
      end
      else begin
        PE <= S7;
      end
    end
    S6 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b1;
      Selecao <= 2'b11;
      PE <= S0;
    end
    S7 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b1;
      PE <= S0;
    end
    endcase
  end
endmodule

module calculator (
    input signed [31:0] a,
    input signed [31:0] b,
    input [1:0] op,
    output reg valid,
    output reg error,
    output reg signed [31:0] add_out,
    output reg signed [31:0] sub_out,
    output reg signed [31:0] mul_out,
    output reg signed [31:0] div_out
);

    // Local variables
    reg signed [31:0] temp;

    // Addition
    always @* begin
        temp = a + b;
        if (a > 0 && b > 0 && temp < 0) begin
            error = 1;
            valid = 0;
        end else if (a < 0 && b < 0 && temp > 0) begin
            error = 1;
            valid = 0;
        end else begin
            error = 0;
            valid = 1;
            add_out = temp;
        end
    end

    // Subtraction
    always @* begin
        temp = a - b;
        if (a > 0 && b < 0 && temp < 0) begin
            error = 1;
            valid = 0;
        end else if (a < 0 && b > 0 && temp > 0) begin
            error = 1;
            valid = 0;
        end else begin
            error = 0;
            valid = 1;
            sub_out = temp;
        end
    end

    // Multiplication
    always @* begin
        temp = a * b;
        if (a != 0 && b != 0 && temp / a != b) begin
            error = 1;
            valid = 0;
        end else begin
            error = 0;
            valid = 1;
            mul_out = temp;
        end
    end

    // Division
    always @* begin
        if (b == 0) begin
            error = 1;
            valid = 0;
        end else begin
            temp = a / b;
            error = 0;
            valid = 1;
            div_out = temp;
        end
    end

    // Output selection
    always @* begin
        case (op)
            2'b00: begin // Addition
                add_out = temp;
                sub_out = 0;
                mul_out = 0;
                div_out = 0;
            end
            2'b01: begin // Subtraction
                add_out = 0;
                sub_out = temp;
                mul_out = 0;
                div_out = 0;
            end
            2'b10: begin // Multiplication
                add_out = 0;
                sub_out = 0;
                mul_out = temp;
                div_out = 0;
            end
            2'b11: begin // Division
                add_out = 0;
                sub_out = 0;
                mul_out = 0;
                div_out = temp;
            end
            default: begin // Invalid operation
                add_out = 0;
                sub_out = 0;
                mul_out = 0;
                div_out = 0;
                error = 1;
                valid = 0;
            end
        endcase
    end

endmodule

