        jtag_break <= probepresent;
        resetlatch <= 1;
    end else if (~debugack & debugreq & probepresent) begin
        jtag_break <= 1'b1;
    end
end

always @(posedge clk or negedge jrst_n) begin
    if (jrst_n == 0) begin
        monitor_ready <= 1'b0;
        monitor_error <= 1'b0;
        monitor_go <= 1'b0;
    end else begin
        if (take_action_ocimem_a && jdo[25]) begin
            monitor_ready <= 1'b0;
        end else if (take_action_ocireg && ocireg_mrs) begin
            monitor_ready <= 1'b1;
        end

        if (take_action_ocimem_a && jdo[25]) begin
            monitor_error <= 1'b0;
        end else if (take_action_ocireg && ocireg_ers) begin
            monitor_error <= 1'b1;
        end

        if (take_action_ocimem_a && jdo[23]) begin
            monitor_go <= 1'b1;
        end else if (st_ready_test_idle) begin
            monitor_go <= 1'b0;
        end
    end
end

