module ALU(
input wire [31:0] Oper1,
input wire [31:0] Oper2,
input wire [5:0] ALUOP,
input wire carry,
output reg [31:0] Salida
);
  always @(ALUOP, Oper1, Oper2) begin
    case(ALUOP)
    6'b000000 : begin
      //ADD
      Salida <= Oper1 + Oper2;
    end
    6'b000001 : begin
      //SUB
      Salida <= Oper1 - Oper2;
    end
    6'b000010 : begin
      //AND
      Salida <= Oper1 & Oper2;
    end
    6'b000011 : begin
      //ANDN
      Salida <= Oper1 &  ~Oper2;
    end
    6'b000100 : begin
      //OR
      Salida <= Oper1 | Oper2;
    end
    6'b000101 : begin
      //ORN
      Salida <= Oper1 |  ~Oper2;
    end
    6'b000110 : begin
      //XOR
      Salida <= Oper1 ^ Oper2;
    end
    6'b000111 : begin
      //XNOR
      Salida <=  ~(Oper1 ^ Oper2);
    end
    6'b001000 : begin
      //SUBcc
      Salida <= Oper1 - Oper2;
    end
    6'b001001 : begin
      // SUBx
      Salida <= Oper1 - Oper2 - Carry;
    end
    6'b001010 : begin
      //SUBxcc
      Salida <= Oper1 - Oper2 - Carry;
    end
    6'b001011 : begin
      //ANDcc
      Salida <= Oper1 & Oper2;
    end
    6'b001100 : begin
      //ANDNcc
      Salida <= Oper1 &  ~Oper2;
    end
    6'b001101 : begin
      //ORcc
      Salida <= Oper1 | Oper2;
    end
    6'b001110 : begin
      //ORNcc
      Salida <= Oper1 |  ~Oper2;
    end
    6'b001111 : begin
      //XORcc
      Salida <= Oper1 ^ Oper2;
    end
    6'b010000 : begin
      //XNORcc
      Salida <=  ~(Oper1 ^ Oper2);
    end
    6'b010001 : begin
      //ADDx
      Salida <= Oper1 + Oper2 + Carry;
    end
    6'b010010 : begin
      //ADDxcc
      Salida <= Oper1 + Oper2 + Carry;
    end
    6'b010011 : begin
      //ADDcc 
      Salida <= Oper1 + Oper2;
    end
    6'b100101 : begin
      //sll
      Salida <= (Oper1) << (Oper2);
    end
    6'b100110 : begin
      //srl
      Salida <= (Oper1) >> (Oper2);
      //SAVE 57
    end
    6'b111001 : begin
      Salida <= Oper1 + Oper2;
      //RESTORE 58
    end
    6'b111101 : begin
      Salida <= Oper1 + Oper2;
    end
    default : begin
      Salida <= {32{1'b1}};
      //error
    end
    endcase
  end
endmodule

module Reset_Synchronizer (
  input rst,
  input clk,
  output rst_sync
);

  reg rst_sync_ff1, rst_sync_ff2;

  always @(posedge clk) begin
    rst_sync_ff1 <= rst;
    rst_sync_ff2 <= rst_sync_ff1;
  end

  assign rst_sync = ~rst_sync_ff2;

endmodule

module freq_counter(
input wire clk,
input wire rst,
input wire pulse,
output reg err,
output reg [15:0] data_out
);
reg [15:0] count; reg [15:0] prev_count;
  // simple counter process
  // max frequency is clk
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      count <= {16{1'b0}};
    end else begin
      count <= count + 1;
    end
  end
  always @(posedge pulse, posedge rst) begin
    if((rst == 1'b1)) begin
      prev_count <= {16{1'b0}};
      data_out <= {16{1'b0}};
    end else begin
      if((prev_count < count)) begin
        data_out <= count - prev_count;
        err <= 1'b0;
      end
      else if((prev_count > count)) begin
        data_out <= prev_count + count;
        err <= 1'b0;
      end
      else begin
        data_out <= {16{1'b0}};
        err <= 1'b1;
      end
      prev_count <= count;
    end
  end
endmodule

module reg_mux(
input wire [3:0] a,
input wire [3:0] b,
input wire [3:0] c,
input wire [3:0] d,
