input wire clk,
output wire [3:0] x,
output reg [3:0] y
);
//------------------------------------
wire [3:0] mux;
  // mutiplexer
  assign mux = sel == 2'b00 ? a : sel == 2'b01 ? b : sel == 2'b10 ? c : d;
  assign x = mux;
  // register
  always @(posedge clk) begin
    y <= mux;
  end
endmodule

module priority_encoder (
    input [7:0] in,
    output reg [2:0] pos
);

always @* begin
    if (in[0]) pos = 0;
    else if (in[1]) pos = 1;
    else if (in[2]) pos = 2;
    else if (in[3]) pos = 3;
    else if (in[4]) pos = 4;
    else if (in[5]) pos = 5;
    else if (in[6]) pos = 6;
    else if (in[7]) pos = 7;
    else pos = 0;
end

endmodule

module counter (
