  output reg [1:0] count
);

  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      count <= 2'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

module nand_gate (
    input a,
    input b,
    output nand_out
);

wire and_out;
wire inv_out;

assign and_out = a & b;
assign inv_out = ~and_out;
