module SerialReceiver(
input wire clk,
input wire rx,
output reg [7:0] data
);
parameter [1:0]
  idle = 0,
  receiving = 1,
  stopbit = 2;
reg [1:0] state = idle;
reg [7:0] temp_data;
reg [31:0] bit_pos = 0;
  always @(posedge clk) begin
    // serial receive
    // XgbvrbgÅcounter_matchªXV
    if(((state == idle) && rx == 1'b0)) begin
      bit_pos <= 0;
      state <= receiving;
    end
    else if((state == receiving)) begin
      temp_data <= {rx,temp_data[7:1]};
      bit_pos <= bit_pos + 1;
      if((bit_pos == 7)) begin
        state <= stopbit;
      end
    end
    else if((state == stopbit)) begin
      if((rx == 1'b1)) begin
        data <= temp_data;
        state <= idle;
      end
    end
  end
endmodule

