    .SetDI(SetDI),
    .SetEI(SetEI),
    .IMode(IMode),
    .Halt(Halt),
    .NoRead(NoRead),
    .Write(Write));
  T80_ALU #(
      .Mode(Mode),
    .Flag_C(Flag_C),
    .Flag_N(Flag_N),
    .Flag_P(Flag_P),
    .Flag_X(Flag_X),
    .Flag_H(Flag_H),
    .Flag_Y(Flag_Y),
    .Flag_Z(Flag_Z),
    .Flag_S(Flag_S))
  alu(
      .Arith16(Arith16_r),
    .Z16(Z16_r),
    .ALU_Op(ALU_Op_r),
    .IR(IR[5:0]),
    .ISet(ISet),
    .BusA(BusA),
    .BusB(BusB),
    .F_In(F),
    .Q(ALU_Q),
    .F_Out(F_Out));
  assign ClkEn = CEN &  ~BusAck;
  assign T_Res = TState == (TStates) ? 1'b1 : 1'b0;
  assign NextIs_XY_Fetch = XY_State != 2'b00 && XY_Ind == 1'b0 && ((Set_Addr_To == aXY) || (MCycle == 3'b001 && IR == 8'b11001011) || (MCycle == 3'b001 && IR == 8'b00110110)) ? 1'b1 : 1'b0;
  assign Save_Mux = ExchangeRp == 1'b1 ? BusB : Save_ALU_r == 1'b0 ? DI_Reg : ALU_Q;
  always @(posedge RESET_n, posedge CLK_n) begin
    if(RESET_n == 1'b0) begin
      PC <= {16{1'b0}};
      // Program Counter
      A <= {16{1'b0}};
      TmpAddr <= {16{1'b0}};
      IR <= 8'b00000000;
      ISet <= 2'b00;
      XY_State <= 2'b00;
      IStatus <= 2'b00;
      MCycles <= 3'b000;
      DO <= 8'b00000000;
      ACC <= {8{1'b1}};
      F <= {8{1'b1}};
      Ap <= {8{1'b1}};
      Fp <= {8{1'b1}};
      I <= {8{1'b0}};
      R <= {8{1'b0}};
      SP <= {16{1'b1}};
      Alternate <= 1'b0;
      Read_To_Reg_r <= 5'b00000;
      F <= {8{1'b1}};
      Arith16_r <= 1'b0;
      BTR_r <= 1'b0;
      Z16_r <= 1'b0;
      ALU_Op_r <= 4'b0000;
      Save_ALU_r <= 1'b0;
      PreserveC_r <= 1'b0;
      XY_Ind <= 1'b0;
    end else begin
      if(ClkEn == 1'b1) begin
        ALU_Op_r <= 4'b0000;
        Save_ALU_r <= 1'b0;
        Read_To_Reg_r <= 5'b00000;
        MCycles <= MCycles_d;
        if(IMode != 2'b11) begin
          IStatus <= IMode;
        end
        Arith16_r <= Arith16;
        PreserveC_r <= PreserveC;
        if(ISet == 2'b10 && ALU_OP[2] == 1'b0 && ALU_OP[0] == 1'b1 && MCycle == 3'b011) begin
          Z16_r <= 1'b1;
        end
        else begin
          Z16_r <= 1'b0;
        end
        if(MCycle == 3'b001 && TState[2] == 1'b0) begin
          // MCycle = 1 and TState = 1, 2, or 3
          if(TState == 2 && Wait_n == 1'b1) begin
            if(Mode < 2) begin
              A[7:0] <= R;
              A[15:8] <= I;
              R[6:0] <= R[6:0] + 1;
            end
            if(Jump == 1'b0 && Call == 1'b0 && NMICycle == 1'b0 && IntCycle == 1'b0 && !(Halt_FF == 1'b1 || Halt == 1'b1)) begin
              PC <= PC + 1;
            end
            if(IntCycle == 1'b1 && IStatus == 2'b01) begin
              IR <= 8'b11111111;
            end
            else if(Halt_FF == 1'b1 || (IntCycle == 1'b1 && IStatus == 2'b10) || NMICycle == 1'b1) begin
              IR <= 8'b00000000;
            end
            else begin
              IR <= DInst;
            end
            ISet <= 2'b00;
            if(Prefix != 2'b00) begin
              if(Prefix == 2'b11) begin
                if(IR[5] == 1'b1) begin
                  XY_State <= 2'b10;
                end
                else begin
                  XY_State <= 2'b01;
                end
              end
              else begin
                if(Prefix == 2'b10) begin
                  XY_State <= 2'b00;
                  XY_Ind <= 1'b0;
                end
                ISet <= Prefix;
              end
            end
            else begin
              XY_State <= 2'b00;
              XY_Ind <= 1'b0;
            end
          end
        end
        else begin
          // either (MCycle > 1) OR (MCycle = 1 AND TState > 3)
          if(MCycle == 3'b110) begin
            XY_Ind <= 1'b1;
            if(Prefix == 2'b01) begin
              ISet <= 2'b01;
            end
          end
          if(T_Res == 1'b1) begin
            BTR_r <= (I_BT | I_BC | I_BTR) &  ~No_BTR;
            if(Jump == 1'b1) begin
              A[15:8] <= DI_Reg;
              A[7:0] <= TmpAddr[7:0];
              PC[15:8] <= DI_Reg;
              PC[7:0] <= TmpAddr[7:0];
            end
            else if(JumpXY == 1'b1) begin
              A <= RegBusC;
              PC <= RegBusC;
            end
            else if(Call == 1'b1 || RstP == 1'b1) begin
              A <= TmpAddr;
              PC <= TmpAddr;
            end
            else if(MCycle == MCycles && NMICycle == 1'b1) begin
              A <= 16'b0000000001100110;
              PC <= 16'b0000000001100110;
            end
            else if(MCycle == 3'b011 && IntCycle == 1'b1 && IStatus == 2'b10) begin
              A[15:8] <= I;
              A[7:0] <= TmpAddr[7:0];
              PC[15:8] <= I;
              PC[7:0] <= TmpAddr[7:0];
            end
            else begin
              case(Set_Addr_To)
              aXY : begin
                if(XY_State == 2'b00) begin
                  A <= RegBusC;
                end
                else begin
                  if(NextIs_XY_Fetch == 1'b1) begin
                    A <= PC;
                  end
                  else begin
                    A <= TmpAddr;
                  end
                end
              end
              aIOA : begin
                if(Mode == 3) begin
                  // Memory map I/O on GBZ80
                  A[15:8] <= {8{1'b1}};
                end
                else if(Mode == 2) begin
                  // Duplicate I/O address on 8080
                  A[15:8] <= DI_Reg;
                end
                else begin
                  A[15:8] <= ACC;
                end
                A[7:0] <= DI_Reg;
              end
              aSP : begin
                A <= SP;
              end
              aBC : begin
                if(Mode == 3 && IORQ_i == 1'b1) begin
                  // Memory map I/O on GBZ80
                  A[15:8] <= {8{1'b1}};
                  A[7:0] <= RegBusC[7:0];
                end
                else begin
                  A <= RegBusC;
                end
              end
              aDE : begin
                A <= RegBusC;
              end
              aZI : begin
                if(Inc_WZ == 1'b1) begin
                  A <= (TmpAddr) + 1;
                end
                else begin
                  A[15:8] <= DI_Reg;
                  A[7:0] <= TmpAddr[7:0];
                end
              end
              default : begin
                A <= PC;
              end
              endcase
            end
            Save_ALU_r <= Save_ALU;
            ALU_Op_r <= ALU_Op;
            if(I_CPL == 1'b1) begin
              // CPL
              ACC <=  ~ACC;
              F[Flag_Y] <=  ~ACC[5];
              F[Flag_H] <= 1'b1;
              F[Flag_X] <=  ~ACC[3];
              F[Flag_N] <= 1'b1;
            end
            if(I_CCF == 1'b1) begin
              // CCF
              F[Flag_C] <=  ~F[Flag_C];
              F[Flag_Y] <= ACC[5];
              F[Flag_H] <= F[Flag_C];
              F[Flag_X] <= ACC[3];
              F[Flag_N] <= 1'b0;
            end
            if(I_SCF == 1'b1) begin
              // SCF
              F[Flag_C] <= 1'b1;
              F[Flag_Y] <= ACC[5];
