module multiplier_block (
    i_data0,
    o_data0
);

  // Port mode declarations:
  input   [3:0] i_data0;
  output  [15:0] o_data0;

  //Multipliers:

  wire [15:0]
    w1,
    w256,
    w257,
    w8224,
    w8225,
    w16,
    w241,
    w964,
    w7261;

  assign w1 = {i_data0, 4'b0};
  assign w16 = w1 << 4;
  assign w257 = w1 + (w1 << 8);
  assign w241 = w257 - w16;
  assign w8224 = w257 << 5;
  assign w8225 = w1 + w8224;
  assign w964 = w241 << 2;
  assign w7261 = w8225 - w964;
  assign o_data0 = w7261;

  //multiplier_block area estimate = 7338.03834891177;
endmodule

module ripple_carry_adder(
  input [3:0] A,
  input [3:0] B,
  input carry_in,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] carry_outs;
  wire [3:0] sums;

  // First full adder
  full_adder FA0(
    .a(A[0]),
    .b(B[0]),
    .c(carry_in),
    .sum(sums[0]),
    .carry_out(carry_outs[0])
  );

  // Second full adder
  full_adder FA1(
    .a(A[1]),
    .b(B[1]),
    .c(carry_outs[0]),
    .sum(sums[1]),
    .carry_out(carry_outs[1])
  );

  // Third full adder
  full_adder FA2(
    .a(A[2]),
    .b(B[2]),
    .c(carry_outs[1]),
    .sum(sums[2]),
    .carry_out(carry_outs[2])
  );

  // Fourth full adder
  full_adder FA3(
    .a(A[3]),
    .b(B[3]),
    .c(carry_outs[2]),
    .sum(sums[3]),
    .carry_out(carry_out)
  );

  assign sum = sums;

endmodule

