module PSR_Modifier(
input wire rst,
input wire [31:0] AluResult,
input wire [31:0] OP1,
input wire [31:0] OP2,
input wire [5:0] AluOp,
output reg [3:0] NZVC
);
  always @(AluResult, OP1, OP2, AluOp) begin
    if((rst == 1'b1)) begin
      NZVC <= {4{1'b0}};
    end
    else begin
      // addcc or addxcc
      if((AluOp == 6'b010011 || AluOp == 6'b010010)) begin
        NZVC[3] <= AluResult[31];
        if((AluResult == 32'h00000000)) begin
          NZVC[2] <= 1'b1;
        end
        else begin
          NZVC[2] <= 1'b0;
        end
        NZVC[1] <= (OP1[31] & OP2[31] & ( ~AluResult[31])) | (( ~OP1[31]) & ( ~OP2[31]) & AluResult[31]);
        NZVC[0] <= (OP1[31] & OP2[31]) | (( ~AluResult[31]) & (OP1[31] | OP2[31]));
      end
      //subcc or subxcc
      if((AluOp == 6'b001000 || AluOp == 6'b001010)) begin
        NZVC[3] <= AluResult[31];
        if((AluResult == 32'h00000000)) begin
          NZVC[2] <= 1'b1;
        end
        else begin
          NZVC[2] <= 1'b0;
        end
        NZVC[1] <= (OP1[31] & ( ~OP2[31]) & ( ~AluResult[31])) | (( ~OP1[31]) & OP2[31] & AluResult[31]);
        NZVC[0] <= (( ~OP1[31]) & OP2[31]) | (AluResult[31] & (( ~OP1[31]) | OP2[31]));
      end
      // operadores logicos
      //  andcc or andncc or orcc or orncc or xorcc or xnorcc
      if((AluOp == 6'b001011 || AluOp == 6'b001100 || AluOp == 6'b001101 || AluOp == 6'b001110 || AluOp == 6'b001111 || AluOp == 6'b010000)) begin
        NZVC[3] <= AluResult[31];
        if((AluResult == 32'h00000000)) begin
          NZVC[2] <= 1'b1;
        end
        else begin
          NZVC[2] <= 1'b0;
        end
        NZVC[1] <= 1'b0;
        NZVC[0] <= 1'b0;
      end
      else begin
        NZVC <= 4'b1000;
      end
    end
  end
endmodule

