output wire [64:1] outbus
);
wire [64:1] rightone; wire [64:1] righttwo; wire [64:1] rightthr;
  genvar k;
  generate for (k=1; k <= 61; k = k + 1) begin: gra
      assign rightone[k] = (inbus[k] &  ~(shift[2]) &  ~(shift[1])) | (inbus[k + 1] &  ~(shift[2]) & shift[1]) | (inbus[k + 2] & shift[2] &  ~(shift[1])) | (inbus[k + 3] & shift[2] & shift[1]);
  end
  endgenerate
  assign rightone[62] = (inbus[62] &  ~(shift[2]) &  ~(shift[1])) | (inbus[63] &  ~(shift[2]) & shift[1]) | (inbus[64] & shift[2] &  ~(shift[1]));
  assign rightone[63] = (inbus[63] &  ~(shift[2]) &  ~(shift[1])) | (inbus[64] &  ~(shift[2]) & shift[1]);
  assign rightone[64] = inbus[64] &  ~(shift[2]) &  ~(shift[1]);
  genvar k;
  generate for (k=1; k <= 52; k = k + 1) begin: grb
      assign righttwo[k] = (rightone[k] &  ~(shift[4]) &  ~(shift[3])) | (rightone[k + 4] &  ~(shift[4]) & shift[3]) | (rightone[k + 8] & shift[4] &  ~(shift[3])) | (rightone[k + 12] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=53; k <= 56; k = k + 1) begin: grc
      assign righttwo[k] = (rightone[k] &  ~(shift[4]) &  ~(shift[3])) | (rightone[k + 4] &  ~(shift[4]) & shift[3]) | (rightone[k + 8] & shift[4] &  ~(shift[3]));
  end
  endgenerate
  genvar k;
  generate for (k=57; k <= 60; k = k + 1) begin: grd
      assign righttwo[k] = (rightone[k] &  ~(shift[4]) &  ~(shift[3])) | (rightone[k + 4] &  ~(shift[4]) & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=61; k <= 64; k = k + 1) begin: gre
      assign righttwo[k] = rightone[k] &  ~(shift[4]) &  ~(shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 48; k = k + 1) begin: grf
      assign rightthr[k] = (righttwo[k] &  ~(shift[5])) | (righttwo[k + 16] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=49; k <= 64; k = k + 1) begin: grg
      assign rightthr[k] = righttwo[k] &  ~(shift[5]);
  end
  endgenerate
  assign outbus = rightthr;
endmodule

