input wire reset,
input wire enable,
output wire zero,
output wire [WIDTH - 1:0] value
);
parameter [31:0] period=4;
parameter [31:0] WIDTH=3;
reg [WIDTH - 1:0] current_count;
reg i_zero;  // Convert the max counter to a logic vector (this is done during synthesis) 
parameter max_count = period;  // Create a logic vector of proper length filled with zeros (also done during synthesis)
parameter zeros = 1'b0;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      // Synchronous reset
      current_count <= max_count;
      i_zero <= 1'b0;
    end
    else if((enable == 1'b1)) begin
      // When counter is enabled
      if((current_count == zeros)) begin
        current_count <= max_count;
        i_zero <= 1'b1;
      end
      else begin
        current_count <= current_count - 1'b1;
        i_zero <= 1'b0;
      end
    end
    else begin
      i_zero <= 1'b0;
    end
  end
  // Connect internal signals to output
  assign value = current_count;
  assign zero = i_zero;
    // Connect internal signals to output
endmodule

module top_module (
    input clk,
    input reset,
    input [7:0] d,
    input mode_select,
    output [7:0] q
);

    reg [7:0] reg_out;
    reg [2:0] counter_out;
    wire [7:0] func_out;

    // Register with active high synchronous reset
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            reg_out <= 8'b0;
        end else begin
            reg_out <= d;
        end
    end

    // 3-bit counter that counts from 0 to 7
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            counter_out <= 3'b0;
        end else if (counter_out == 3'b111) begin
            counter_out <= 3'b0;
        end else begin
            counter_out <= counter_out + 1;
        end
    end

    // Load counter with register output on reset
    always @(posedge clk, negedge reset) begin
        if (reset == 1'b0) begin
            counter_out <= reg_out[2:0];
        end
    end

    // Functional module that performs XOR or XNOR operation
    xor_xnor_module xor_xnor_inst (
        .a(counter_out),
        .b(reg_out),
        .mode(mode_select),
        .y(func_out)
    );

    // Output the result of the functional module
    assign q = func_out;

endmodule

module xor_xnor_module (
    input [2:0] a,
    input [7:0] b,
    input mode,
    output [7:0] y
);

    always @(*) begin
        if (mode == 1'b0) begin
            y = a ^ b;
        end else begin
            y = ~(a ^ b);
        end
    end

endmodule

module freq_divider (
  input clk,
  input rst,
  input [3:0] div_factor,
  output reg clk_out
);

// The module has a 4-bit control input, which allows for division factors of up to 16.
// The default division factor is 2.
parameter DEFAULT_DIV_FACTOR = 2;
parameter MAX_DIV_FACTOR = 16;

initial begin
  clk_out <= 0;
end

reg [3:0] count;

always @(posedge clk or negedge rst) begin
  if (~rst) begin
    clk_out <= 0;
    count <= 0;
  end
  else begin
    if (count >= div_factor - 1) begin
      count <= 0;
      clk_out <= ~clk_out;
    end
    else begin
      count <= count + 1;
    end
  end
end

endmodule
